(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["466"] = {"atoms": {"466.1": {"x": [[59, "ثم إن صانع العالم أوجده باختياره، إذ من لا اختيار له في فعل فهو مضطر، والمضطر عاجز، ولا اختيار بدون الإرادة، فكان مريداً، وبه بطل قول النظام والكعبي ومن ساعدهما من البغدادية، يحققه: أن الإرادة معنى يوجب اختصاص المفعولات به بوجه دون وجه، إذ لو لا الإرادة لوقعت المفعولات كلها في وقت واحد على هيئة واحدة وصفة واحدة خصوصاً عند تجانس المفعولات، فإذا خرجت عن الترادف والتوالي وعلى النظام والاتساق وعلى الهيئات المختلفة والصفات المتباينة على حسب ما تقتضيه الحكمة البالغة والتدبير الصائب كان ذلك دليلاً على اتصاف الفاعل بالإرادة؛ إذ لو لا الإرادة لما كان وقت لوجوده أولى من وقت، ولا هيئة أولى من هيئة، ولا كيفية ولا كمية أولى من سواهما. ثم لما كان مريداً علن أنه ليس بمريد لذاته ــ كما ذهبت إليه النجارية ــ لأن ذاته تعالى ليس بإرادةٍ، وكن الذات مريداً بما ليس"], [60, "بإرادة ككونه عالماً بما ليس بعلم أو متحركاً ليس بحركة أو أسود بما ليس بسواد، وهو تجاهل، ودلالة ذلك قد مرت في مسألة الصفات. وليس بمريد بإرادة حادثة لا في محل ــ كما ذهب إليه البصريون من المعتزلة ـــ لأنها لو حدثت بإحداث أحد فهو محال، وتجويزه يوجب تجويز وجود العالم وحدوثه بلا محدث، والقول به يؤدي إلى تعطيل الصانع، ولو جاز ذا لجاز ذلك في جميع العالم وأدى القول به إلى إبطال القول بالصانع وهو محال؛ ولو حدثت بإحداث الصانع إما أن حدثت لا بإرادة منه وهو محال؛ لأنه يوجب كونه مضطراً في إحداث الإرادة، وإما أن أحدثها بإرادة الإرادة، والكلام في الإرادة الثانية كالكلام في الأولى، وكذا في الثالثة والرابعة إلى ما لا يتناهى، والقول به محال، ولأنها لو حدثت لا في محل لم يكن الله تعالى بالاتصاف بها أولى من غيره، ولا هي بكونها إرادة له أولى من أن تكون إرادة لغيره، والله الموفق.\rوليس بمريد أيضاً بإرادة حادثة في ذات الله تعالى ــ كما ذهبت إليه الكرامية ــ لما مر من استحالة كون الذات القديم محل الوارث، ولما مر أن حدوثها بالأحداث محال، وحدوثها بالإحداث بغير إرادة أخرى محال أيضاً، وكذا حدوثها بإرادة أخرى لما مر أنه يؤدي إلى ما لا"], [61, "يتناهى، وإذا بطلت الوجوه كلها ثبت أنه تعالى مريد بإرادة أزلية قائمة بذاته هي إرادة لكل مراد لوقت وجوده، والله الموفق."], [62, "فصل في أن صانع العالم حكيم\r"]], "pg": [59, 62]}, "466.2": {"x": [[62, "ثم إن صانع العالم حكيم، فإن الحكمة إن كانت من باب العلم والحكيم هو العالم كما قال ابن الأعرابي فلا شك أنه تعالى كان في الأزل عالماً وهو لايزال عالماً لا تتبدل عليه الصفات.\rوإن كانت من باب الفعل وهي: \"الإحكام للمفعولات\"، والحكيم هو المحكم كالأليم بمعنى المؤلم، فالله تعالى هو المحكم للمخلوقات أجمع، ثم سواء كانت الحكمة من باب العلم وضدها الجهل أو من باب الفعل وضدها السفه، إذ هو المنافي للأحكام، إذ السفه عبارة عن خفة تعتري الفاعل إما من الفرح أو من الغضب فتبعثه على فعل من غير رؤية ولا قصد للأحكام، فالله تعالى بها موصوف في الأزل، إذا العلم عندنا كما هو أزلي فالفعل الذي هو التكوين أيضاً أزلي، فكان حكيماً لم يزل كما كان عالماً قادراً خالقاً رازقاً في الأزل على ما مر في مسألة التكوين، وأبو الحسن الأشعري لما عرف اختلاف أهل اللغة في الحكمة، وكان من مذهبه القول بقدم صفات الذات وحدوث صفات الفعل ذهب إلى أن الحكمة أريد بها الفعل فلا يكون موصوفاً بها في الأزل على ما مر في"], [63, "مسألة التكوين والمكون، وأبو العباس القلانسي جعلها من باب الفعل، ولم يقل بأزليتها على ما هو مذهبهم، وقد مر فيه الكلام، والله الموفق."], [64, "فصل في إثبات رؤية الله تعالى في العقل دليل على جواز رؤية الله تعالى\r\r"]], "pg": [62, 64]}, "466.3": {"x": [[64, "وقد ورد الدليل السمعي بإيجاب رؤية المؤمنين الله تعالى في الدار الآخرة، فيرى لا في مكان ولا على جهةٍ من مقابلة أو اتصال شعاع أو ثبوت مسافة بين الرائي وبينه تعالى، وغير ذلك من المعاني التي هي من أمارات الحدث، وزعمت المعتزلة والنجارية والخوارج أن في العقل دلالة كون رؤية الله تعالى مستحيلاً؛ إذ الرؤية لا تتعلق إلا بالجسم ولابد لها من مقابلة بين الرائي والمرئي وثبوت مسافة بينهما واتصال شعاع عين الرائي بالمرئي، وكل ذلك يستحيل على الله تعالى، وأكد هذا المعقول قوله تعالى: {لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ} [الأنعام: 103]، وفيه التمدح بانتفاء الإدراك وهو الرؤية، وما يتمدح بانتفائه لا يتبدل استحالة ثبوت ذلك بتبدل المحال كالولد والصاحبة والشريك وأشباه ذلك.\rــ وحجة أهل الحق في ذلك: أن موسى عليه السلام سأل الله تعالى ما هو محال عنده فكان سؤاله دليلاً أنه كان يعتقد أن الله تعالى جائز الرؤية، فمن زعم أن رؤية الله تعالى مستحيلة فقد زعم أن موسى عليه"], [65, "السلام لم يكن عارفاً بالله تعالى، إذ اعتقد عليه جواز ما لا جواز له عليه، ومن نسب موسى عليه السلام إلى الجهل بالله تعالى فقد كفر، ثم إن الله تعالى ما أيأسه بل علق ذلك بشرط متصور الكون في الجملة وهو: \"استقرار الجبل\"، ولا تعلق بالممكن إلا ما هو ممكن الثبوت، وكذا الله تعالى وعد المؤمنين ذلك في الدار الآخرة بقوله: {وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ (22) إِلَى رَبِّهَا نَاظِرَةٌ (23)} [القيامة: 22، 23]، والنظر المضاف إلى الوجه المعدي بكلمة \"إلى\" لن يكون إلا نظر العين، ولا تعلق للخصم بقوله تعالى: {لَا تُدْرِكُهُ الْأَبْصَارُ} [الأنعام: 103]؛لأن المنفي هو الإدراك لا الرؤية، والإدراك: \"هو الوقوف على جوانب المرئي وحدوده\"، وما يستحيل عليه الحدود والجهات يستحيل عليه الإدراك دون الرؤية؛ فكان الإدراك من الرؤية نازلاً منزلة الإحاطة من العلم، ونفي الإحاطة التي تقتضي الوقوف على الجوانب والحدود لا تقتضي نفي العلم به، فكذا هذا، ثم مورد الآية وهو التمدح يوجب ثبوت الرؤية؛ إذ نفى الإدراك لما يستحيل عليه الرؤية لا تمدح فيه؛ إذ كل ما لا يرى لا يدرك، وإنما التمدح بنفي الإدراك مع تحقق الرؤية هو الموجب"], [66, "للتمدح؛ إذ انتفاؤه مع ثبوت الرؤية دليل ارتفاع نقيضة التناهي والحدود عن الذات، فكانت الآية حجة لنا على الخصوم، ولو أنعموا النظر فيها وعرفوا مواقع الحجاج لاغتنموا التقصي عن عهدة الآية، والله الموفق. والمعقول أنا نرى في الشاهد الجواهر والألوان والأكوان إذ كما تميز بحاسة البصر بين جوهر وجوهر تميز بين الأبيض والأسود والمتحرك والساكن والمجتمع والمفترق، ولو كان السواد والبياض والحركة والسكون والاجتماع والمفترق، ولو كان السواد والبياض والحركة والسكون والاجتماع والافتراق غير مرئية ولم ير إلا الجواهر لما وقع التميز بين الأبيض والأسود والمتحرك والساكن كما لا يقع بين العالم والجاهل والفيه والساخط والراضي، ثم لما ثبت رؤية هذه المعاني ولم نعلن وضعاً جامعاً بين هذه الأجناس إلا الوجود؛ إذ لا جوهرية في الألوان والأكوان، ولا لونية في الجواهر، وكذا لا عرضية فيها، وكذا لا جوهرية ولا لونية في الحركة والسكون، وعند السبر يتبين أن ليس وراء الوجود صفة تجمع هذه الأجناس، فعلمنا أن المعنى المطلق للرؤية المجوز لها ليس إلا الوجود، وما لا يرى من الموجودات فلعدم إجراء الله تعالى العادة في إثبات رؤيتنا لها لا لاستحالتها، والوجود علة مطلقة مجوزة للرؤية لا موجبة لها.\rرأينا أن الوجود يتعدى من الشاهد إلى الغائب فيكون جائز الرؤية في العقل، ثم الشرع ورد بإثباتها في الأخرة للمؤمنين، وعرف بهذا بطلان تعليقهم الرؤية بالجسم لما مر من رؤية ما ليس بجسم، وما"], [67, "يذكرون من اشتراط المقابلة وثبوت المسافة واتصال الشعاع وتحقق الجهة فهو كله باطل؛ فإن الله تعالى يرانا من غير مقابلة ولا اتصال شعاع ولا مسافة بيننا وبينه ولا جهة، والعلل والشرائط لا تتبدل بالشاهد والغائب، وحيث تبدلت دل أنها من أوصاف الوجود دون القرائن اللازمة.\rفلا يشترط تعديتها، وهذا لأن المرئي إن كان في جهة أو مقابلة يرى فيها لا لأن الرؤية تقتضي ذلك لا لأن المرئي كذلك، وكل شيء يرى على ما هو عليه، وفي الغائب الأمر بخلافه، واعتبر هذا بالعلم فإن كل شيء يعلم كما هو إن كان في الجهة يعلم في الجهة، وإن كان لا في الجهة يعلم لا فيها، فكذا الرؤية.\rوما يزعم بعض جهالهم أن الرؤية تقتضي التشبيه ــ فلو كان الله تعالى مرئياً لكان شبيهاً بالمرئيات ــ باطل؛ لأن الرؤية في الشاهد تتعلق بالمتضادات كالسواد والبياض والحركة والسكون، ولا مشابهة بينهما فكذا فيما نحن فيه، يحققه أن إنساناً لو ألزم هذا في العلم وقال: \"إن العلم يقتضي التشبيه، فلو كان الله تعالى معلوماً لكان شبيهاً بالمعلومات\"، يبطل قوله بما مر من تعلق العلم بالمتضاد مع أنه لا مشابهة بينهما فكذا هذا، والله تعالى الموفق."], [68, "فصل في إثبات الرسالة\r"]], "pg": [64, 68]}, "466.4": {"x": [[68, "ولما ثبت أن للعالم صانعاً حكيماً عليماً، وكل جزء من أجزاء العالم ملكه لا شريك له فيه لما مر كم دلائل وحدانيته تعالى، فنقول: إن ورود التكليف بالإيجاب والحظر والإطلاق والمنع ممن له الملك في ممالكيه مما يأباه العقل أو يحكم بامتناعه؛ إذ لكل مالك ولاية التصرف في مملوكه بقدر ما له من الملك، ولله تعالى في كل جزء من أجزاء العالم وأشخاص بني آدم ملك التخليق؛ إذ هو الموجد له من العدم والمخترع له لا عن أصل، فكان له أن يتصرف في كل من ذلك على أي وجه شاء من وجوه التصرف، ثم يعلمهم ذلك باي طريق شاء، إن شاء فعل ذلك بتخليق العلم لهم بذلك، وإن شاء فعل ذلك بإرسال رسول إلى المكلف من جنسه أو من خلاف جنسه على أن البشر مهيأ لقبول الحكمة والعلم معد للزيادة وبلوغ درجة الكمال عند إفادة الحكيم المرشد إياه؛ إذ هو ممن يجوز عليه الجهل ولا يمتنع عليه قبول العلم بالتعليم، ثم إن صانع العالم هو الحكيم الذي لا يسفه، العليم الذي لا يجهل، وهو الموصوف بالرأفة والرحمة على عباده فلا يمتنع منه إمداد المجبولين على النقيصة بما يوجب زوالها ويورث لهم الكمال وبلوغ الدرجة العالية في الحكمة والعلم، وبالوقوف على هذه الجملة يعرف أن إرسال الرسل مبشرين ومنذرين ليبثوا للناس ما يحتاجون إليه من مصالح دارهم"], [69, "و يفيدهم من أنواع الحكم ما يبلغون به درجة الكمال في حيز الإمكان دون الامتناع، يحققه أن الأوامر الواردة من الصانع الحكيم على ألسنة سفرائه من رسله وأنبيائه عليهم السلام كلها مما ينتفع بما أمر به المأمورون ويندفع الضرر بالامتناع عما نهى عنه المنهيون. ثم إن من أمر أعمى لسوك الطريق الجادة الموصلة له إلى مقصده الذي ينتفع به ببلوغه إليه أتم الانتفاع، ونهاه عن أن يحيد يمنة ويسرة ــ كما أن في الحيد عنه إلى ذلك وقوعه في المهاوي والمهالك ـــ عد ذلك منه حكمة بل رأفة ورحمة. فمن عده ممتنعاً فهو الجاهل بالامتناع والإمكان.\rثم بعد ثبوت إمكانه في العقول نقول:\rلا شك أن فيما خلق الله تعالى من جواهر العالم ما يتعلق به مصلحة أبدان الخلق نت الأغذية التي لا بد لقوام مهجتهم بها، والأدوية التي بها يحصل حفظ الصحة الثابتة وإزالة العلل العارضة، وما يحصل"], [70, "بتناوله التلف والهلاك بأسرع مدة وهو السموم القاتلة، وليس في قوى العقول الوقوف على طبائعها والاطلاع على ما فيها من المصالح والمفاسد، فلو لم يرد البيان ممن هو العالم بحقائقها لننتفع بما فيه المنفعة ونجتنب ما يفه المضرة لم يكن لخلق كل جوهر من ذلك على ما خلقه عليه من المنفعة والمضرة حكمة.\rولما أمكن للخلق الوصول إلى ما هو المخلوق سبباً لبقائهم والتمييز ما بينه وبين ما في الإقدام على تناوله عطبهم وهلاكهم، والعقل لا يطلق التجربة بنفسه مع ما فيه من خطر والهلاك فلابد من بيان يرد ممن له العلم بذلك؛ لئلا يؤدي الامتناع عن البيان إلى فناء أبدان الممتحنين من غير تعلق عاقبة حميدة بتخليقهم لما فيه من تخليق الخلق للفناء خاصة وهو خارج عن قضية الحكمة، يحققه ان البشر لو أمكنهم الوصول إلى ذلك بما لهم من العقول لفعلوا، ثم كل منهم جبل على حب البقاء وطلب ما يحصل له به الدوام، فلو لم يشرع الحكيم شرعاً ولم يضع أسباباً يكون المختص بها مختصاً بم لها من الأحكام، وينقطع عن الأعيان طمع من لم يقر بالاختصاص بسبب تملكه؛ لتسارع كل إلى ما يميل إليه طبعه ويعرف فيه بقاؤه ويرجو الاستمتاع به، وفي ذلك وقوع المنازعة والعداوة وذلك بسبب تولد الضغائن والأحقاد، وكل ذلك مما يحمل على التقاتل والتفاني، وفيه فناء الخلق وانقطاع نسل البشر وارتفاع"], [71, "جنسهم وهم المقصودون بتخليق العالم، وفيه أيضاً تخليق الخلق للفناء خاصة، وفي إرسال الرسل عليهم السلام ووضع الشرائع حصول العاقبة الحميدة للتخليق، ورفع لأسباب العيث والفساد عما بين العباد. فمن أنكر الشرع وأبطل الأمر والنهي فقد سعى في إثارة كل فتنةٍ في العالم وفساد في الدنيا، وبالله العصمة عن كل ضلالةٍ.\rيحققه أن في قوى العقول الوقوف على جمل المحاسن والمساوئ دون أعيانها، والشرف والحكمة في الوقوف على الأعيان دون الجمل، فلابد من ورود البيان ممن له العلم بحقيقة كل فرد من أفراد تلك الجمل أنه من جملة المحاسن أو من جملة القبائح ليحمل العقل بميلانه إلى المحاسن صاحبه إلى مباشرته وبنفاره عن القبائح على الانتهاء عنها، لولا ذلك لم يحصل لتخليق العقل مائلاً إلى المحاسن نافراً عن القبائح عاقبة حميدة، وذلك ليس بحكمة، يؤيده أن العقول لما دعته إلى المحاسن ونفرته عن القبائح ولا وقوف لها على أعيان الجنسين فكان فيه المر بم لا وصول له إلى مباشرته والنهي عما لا وجه إلى الانتهاء عنه،"], [72, "وذلك ليس بحكمة، فلابد من البيان الوارد في حق كل عين، وليس ذلك إلا للشرع والله الموفق.\rوالذي يؤيد هذا كله أن وجوب شكر المنعم مودع في العقول لما فيه من الحسن، وحظر الكفران كذلك، وليس في العقول الوقوف على قدر النعم وما يوازيها من الشكر، فلابد من الشرع الوارد ببيان لك ليتمكن المكلف من أداء ما كلف أداءه والامتناع عما منع عن تعاطيه، والله الموفق.\rوراء ذلك وجوه كثيرة يتبين بها الوقوف على القول بصحة الرسالة ذكرناها في كتابنا المترجم بـ \"تبصرة الأدلة\"، وفي هذا القدر الذي ذكرناه في هذا الكتاب كفاية لمن عقل وأنصف.\rثم الرسالة وغن كانت عند كثير من المتكلمين في حيز الممكنات وعند أصحابنا هي من مقتضيات الحكمة على ما قررناه، فإذا جاء واحد وادعى أصحابنا هي من مقتضيات الحكمة على ما قررناه، فإذا جاء واحد وادعى الرسالة في زمان جواز ورود الرسل وهو قبل مبعث نبينا المصطفى صلى الله عليه وسلم إذ لم يثبت بالنص الوارد انختام الرسالة وانسداد بابها، وادعى هذا الجائي أنه رسول الله، كان يجب التأمل في دعواه، فإن كانت"], [73, "الدعوى ممتنعة كدعوى \"زرادشت\" بصانعين عاجزين! ودعوى \"ماني\" بأصلين قديمين: النور والظلمة! مع ما في العقول من تقرر استحالتهما، كان يجب الرد بأول ما قرعت الدعوى السماع لا الاشتغال بطلب البرهان؛ إذ لا دلالة تقوم على تصحيح الممتنع إلا إذا أريد بذلك تأكيد في إظهار كذبه، إذ من المعلوم الذي ريب فيه أنه لا يتمكن من إقامة الدليل فينتهك ستره حينئذٍ ويفتضح في دعواه، وإن كانت دعواه"], [74, "ممكنة لا يجب قبول قوله بدون إقامة الدليل بخلاف ما يقوله الإباضية من الخوارج من وجوب قبول مدعى الرسالة بدون إقامة الدليل لما أن تعين هذا المدعى للرسالة ليس من حيز الواجبات لانعدام دلالة العقل على تعينه فبقي في حيز الممكنات، وربما يكون كاذباً في دعواه، فكان القول بموجب قبول قوله قولاً بوجوب قبول قول من يكون قبول قوله كفراً، وهذا خلف من القول.\rوإذا لم يجب قبول قوله بدون الدليل يطالب بالدليل وهو المعجزة، وحدها على طريقة المتكلمين: أنها ظهور أمر بخلاف العادة في دار التكليف لإظهار صدق مدعى النبوة مع نكول من يتحدى به عن معارضته بمثله.\rوإنما قيدنا بـ \"دار التكليف\"؛ لأن ما يظهر من النقائض للعادة في الدار الآخرة لا يكون معجزة، وإنما قلنا: \"لإظهار صدق مدعى النبوة\"؛ ليقع الاحتراز به عما يظهر على يدي مدعي الألوهية، إذ ظهور ذلك"], [75, "على يده جائز عندنا، وفيه أيضاً احتراز عما يظهر على يدي الولي إذ ظهور ذلك كرامة للولي جائز عندنا، وإنما قلنا: \"لإظهار صدقه\"؛ لأن ذلك لو ظهر لإظهار كذبه بأن قال: \"الدليل على صحة نبوتي أن هذا الحجر يشهد لي\"، فأنطق الله تعالى الحجر بتكذيبه لا يكون ذلك معجزة له ودليلاً على صدقه، بل يكون دليلاً على كذبه في دعواه، وإنما قلنا: \"مع نكول من يتحدى عن معارضته بمثله\"؛ لأن الناقض للعادة لو ظهر على يده ثم ظهر على يدي المتحدي مثله الذي ظهر على يدي من يكذبه يكون دليل صدق تكذيبه، فيكون دليل كذبه، فيتعارض الدليلان فيسقطان، والله الموفق."], [76, "ثم إذا ظهرت المعجزة على الحد الذي بيناً على يدي مدعي النبوة كانت دلالة على صدق المدعى، ووجه الدلالة: ما تقرر في عقولنا أن الله سامع دعوى هذا المدعي، وأن ما ظهر على يده خارج عن مقدور البشر بل عن مقدور جميع الخلائق ولا قدرة عليه إلا لله تعالى، فإذا ادعى الرسالة ثم قال: \"آية صدق دعواي أن الله تعالى أرسلني أن يفعل كذا\"، ففعل الله تعالى ذلك، كان ذلك من الله تعالى تصديقاً له فيما يدعي من الرسالة بما فعل من نقض العادة، فيكون ذلك كقوله له عقب دعواه هذه: \"صدقت\"، وهذا ظاهر في المتعارف، والله الموفق.\rثم قد ثبت بوقوف الناس على طبائع الجواهر وما هو غذاء منها وما هو داء وسم مع أنه ليس في قوى عقولهم أو حواسهم إمكان الوقوف على ذلك، وأنهم أوقفوا على ذلك بإعلام خالقها على لسان من أرسل إليهم بإعلام ذلك، فثبت به أنه فيما مضى من الأزمنة كانت الرسالة ثابتة في الجملة، ثم على سبيل التعيين فالدين ثبت بالتواتر الموجب للعلم قطعاً ويقيناً أنه ظهرت على أيديهم المعجزات الناقضات للعادات كقلب العصا حية، واليد البيضاء، وانفلاق البحر، وإبراء الأكمه والأبرص، وإحياء الموتى، وإخراج الناقة من الحجر، وتسخير الجن والشياطين والطيور،"], [77, "وغير ذلك. ثبتت نبوتهم بما اقترن بدعاويهم من هذه الآيات الخارجة عن طوق البشر المباينة حيل المحتالين، المجاوزة قوى المخرقين، الزائدة عند شدة التفحص والتأمل صحة ووكادة، مخالفة في ذلك الحيل والتمويهات التي تظهر عند البحث عنها وجوه بطلانه. ثم إن من كان مساوياً لهم في الدعوى والبرهان ووجه دلالة البرهان كان مساوياً لهم في صحة الدعوى. ثم إن نبينا المصطفى محمد بن عبد الله بن عبد المطلب بن هاشم بن عبد مناف صلى الله عليه وسلم سلوى غيره من الأنبياء عليهم السلام في المعجزات، بل اجتمع في حقه من وجوه الدلائل ما لم يوجد ذلك لغيره، فأما آياته الحسية: فما ثبت له من العجائب المخالفة لمجرى الطبائع والبدائع المفارقة للمعهود من العادة، منها ما هو خارج ذاته، كانشقاق القمر، واجتذاب الشجر، وتسليم الحجر عليه، ونبع الماء بين أصابعه، وحنين الخشب، وشكاية الناقة، وشهادة الشاة المصلية، وشرب الكثير من البشر القليل من الماء، وما كان من السحاب الذي كان يظلله قبل مبعثه، وغير ذلك مما لا يحصى منها ما هو في ذاته كالنور الذي ينتقل من ظهر إلى بطن ومن بطن إلى ظهر إلى أن خارج، وما كان من"], [78, "الخاتم بين كتفيه، وما روى أنه كان ربعة ثم كان لا يزاحم طويلين إلا فاقهما، وما روى أنه لو نظر إلى وجهه والبدر فكان أحسن، وأنه كان أطيب ريحاً من المسك، وألين كفاً من الحرير، وكان يؤخذ عرقه فينتفع به في الطيب، وقد وصفت خلقته بما لا يعرف أحد يوصف بمثله حسناً وجمالاً، وقد وصفه على التفصيل وبينه هند بن أبي هالة وأم معبد مما لولا إطالة الكتاب لأوردته. ثم إن أصحاب علم الفراسة مجمعون معترفون أن اجتماع هذه الصفات في البدن الواحد مما يقل وجوده ويعز اتفاقه، وهو مع ذلك دال على أن النفس المختصة بمثل هذا التركيب تكون لا محالة أشرف النفوس وأتمها، فيكون دلالة صادقة بشهادة علم الفراسة أنه صادق خير غير شرير ولا كاذب، والله الموفق.\rومنها ما كان في أخلاقه: وهو أنه عليه الصلاة والسلام لم يوجد عليه كذب قط، ولا عرفت منه هفوة، ولا منه عن أعدائه فرار، بل كان في الشجاعة بمحل ما ولى دبره قط، على ما أصاب أتباعه من النكبات والشدائد؛ ولذلك أمكنه الركون إلى وعد الله تعالى بقوله: {وَاللَّهُ"], [79, "يَعْصِمُكَ مِنَ النَّاسِ} [المائدة: 67]، ولم يعرف في أخلاقه سوء بل كان على ما وصف لا يداري ولا يماري، وما كان فاحشاً ولا صخاباً، وكان في الإشفاق بالمحل الذي عوتب عليه بقوله تعالى: {فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ} [فاطر: 8]، وقوله: {فَلَعَلَّكَ بَاخِعٌ نَفْسَكَ} [الكهف: 6]، وكان في السخاء والكرم بحيث عوتب عليه بقوله: {وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ} [الإسراء: 29].\rوفي الجملة كان النبي عليه السلام في حلمه ووقاره، وزهده وسخائه، وأمانته وسداده، وشجاعته وعفافه، وصادق خبره وذكاء فهمه، وقلة تلونه وبارع حفظه، وقوله بجوامع الكلم إذا قال، وبمراعاته شرائط الصمت إذا صمت، وتصديقه المواعيد إذا وعد، وطهارة أخلاقه كلها صبياً وناشئاً كلها بحيث يتبع أثاره أعداؤه، ثم كانت هذه الأخلاق الفاضلة والشمائل الشريفة موجودة على طول الزمان وتصاريف الأحوال، لم يتغير في شيء منها في حالة ولا وجد منه ضد من أضدادها طول عمره، وكان ذلك دليلاً على أن شيئاً منها لم يكن عن تكلف؛ إذ التخليق يأتي دونه الخلق، فكان جريه عليه السلام على ذلك في الأزمنة والدهور دليلاً أنها مواهب من الله تعالى له؛ ليكون اجتماعها كلها وانتفاء أضدادها دلالة صادقة له أنه المؤيد بقوة سماوية، والمكرم بمعونة إلهية ليشتغل بالقيام بما فوض إليه، وتحمل أعباء ما حمل عليه من أمور"], [80, "الرسالة إلى أصناف الخليقة. ثم اجتماع هذه المعاني التي اجتمعت في بدنه وأخلاقه خارج عن العادة المستمرة وإن كان وجود أفرادها على ما عليه العادة، ولن نظن أن الله تعالى مع كمال حكمته يجمع هذا كله فيمن يعلم أنه يتقول عليه ويدعي أنه أرسله إلى عباده إفكاً منه وتخرصاً، ولو كان هذا جائزاً لكان إظهار المعجزة الناقضة للعادة على يدي المتنبي أجوز، وقد مر امتناع ذلك فكذا هذا.\rومعجزاته العقلية الحسية مما لا يحصى كثرة، ذكرها نقلة الحديث وخلدوها في كتبهم، وكتابنا هذا لا يضيق عن ذكر ذلك كله، وفيما ذكرته كفاية لمن عقل وأنصف.\rومعجزاته العقلية منقسمة إلى أقسام كثيرة: "]], "pg": [68, 80]}, "466.5": {"x": [[80, "منها راجع إلى أخباره، وهذا ينقسم إلى قسمين:\rأحدهما: ما ورد من البشارات به في الكتب المتقدمة والأمم الماضية.\rوالثاني: إخباره عن الكائنات، وهذا القسم الأخير ينقسم إلى قسمين:\rأحدهما: إخباره عن أمور ماضية.\rوالثاني: إخباره عن أمور توجد في المستقبل، ومنها ما ظهر بعد وفاته، ومنها ما هو راجع إلى مكانه، ومنها ما هو راجع إلى زمانه،"], [81, "ومنها ما هو راجع إلى كتابه الذي أتي به، ومنها ما هو راجع إلى شريعته التي اختص بها.\rوقد بينت كل فصل من هذه الفصول وكل قسم من هذه الأقسام في كتاب \"تبصرة الأدلة\" بما هو يوجب العلم قطعاً، ويقطع عذر كل جاحد، ويفحم كل معاند، وكتابنا هذا لا يسع لذكر ذلك فأعرضت عن ذكره مخافة الإطالة واعتماداً على ما ذكرت في الكتاب، والله تعالى الهادي إلى الرشاد."], [82, "فصل في إثبات كرامات الأولياء\r"]], "pg": [80, 82]}, "466.6": {"x": [[82, "وظهور الكرامة على طريق نقض العادة للولي جائز غير ممتنع، وأنكرت المعتزلة ذلك؛ لما أنهم لم يروها في أنفسهم لخروجهم عن الولاية بسبب ضلالتهم وشؤم بدعتهم؛ ولأنهم ظنوا أن ذلك لو جاز لانسد طريق الوصول إلى معرفة النبي والرسول؛ ولأن الفائدة في ظهورها منعدمة بخلاف المعجزة فإن الحاجة إلى معرفة النبي من المتبني ماسة ولا حاجة إلى معرفة الولي من غيره، إذ ليس فيه تكليف الاعتقاد بولايته.\rوأهل الحق أقروا بذلك لما اشتهر من الأخبار واستفاض من الحكايات عن الأخبار، كما روي عن رؤية عمر ـــ رضي الله عنه ـــ على المنبر بالمدينة جيشه بنهاوند حتى قال: \"يا سارية الجبل الجبل\"، وسمع سارية الصوت على ما هو المشهور.\rوروى عن خالد ــ رضي الله عنه ــ أنه شرب السم بالحيرة فلم يضره. وذلك مشهور مستفيض.\rوحديث صاحب سليمان صلوات الله عليه وسلامه، وإتيانه بعرش بلقيس قبل ارتداد الطرف من تلك المسافة الممتدة مذكور في القرآن لا يجحد ذلك إلا من كفر بالقرآن وبالنبي محمد عليه السلام، فلا وجه إلى"], [83, "إيراد ما انتشر به الخبر عن صالحي الأمة في ذلك. ثم ما ظنوا أنه يؤدي إلى انسداد طريق الوصول إلى معرفة النبي عليه السلام فظن باطل، بل كل كرامة للولي تكون معجزة للرسول، فإن بظهورها يعلم أنه ولي، ولن يكون ولياً إلا أن يكون محقاً في ديانته الإقرار برسالة رسوله واتباعه إياه في دينه دليل صحة رسالة رسوله، فمن جعل ما هو معجزة للرسول ودلالة صدقه مبطلاً للمعجزة تظهر على أثر الدعوى، والولي لو ادعى الرسالة لكفر من ساعته وصار عدواً لله تعالى، ولا يتصور بعد ذلك ظهور الكرامة يجتهد في كتمانها ويخاف الاغترار لدى الاشتهار. ثم إذا ثبتت الكرامة يجتهد في كتمانها ويخاف أنها من قبيل الاستدراج له دون المعجزة، ويخاف الاغترار لدى الاشتهار. ثم إذا ثبتت الكرامة بما مر فجهل المعتزلة بما فيها من الحكمة لا يوجب امتناع وجودها، ثم فيها فائدة ثبوت رسالة من آمن به الولي، وصيرورة الولي كمن عاين من أهل عصر النبي معجزته، وتصير أيضاً مبعثة له على الاجتهاد في العبادات والاحتراز عن السيئات إبقاء لتلك المنزلة العلية والدرجة الشريفة على نفسه، وحفظاً لتلك المنزلة العلية والدرجة الشريفة على نفسه، وحفظاً لتلك المرتبة عن التبدل والزوال، ويصير تحريضاَ لمن أطلعه الله تعالى عليها من الصالحين على الجد"], [84, "والاجتهاد، وليبلغ تلك الدرجة وينال تلك المنزلة ويساوي من ظهرت له من الفضيلة، والله تعالى الموفق.\rوإذا ثبت أن الصانع جل وعلا حكيم، وإرسال الرسل لا ينافي حكمته بل هو من مقتضيات حكمته، وكذا إظهار الناقض للعادة على يدي الولي مما ليس ينافي الحكمة، فبعد ذلك نشتغل مسائل التعديل والتجويز إذ هي مما اختلفنا نحن والخصوم في كونها حكمة أو سفها، فنذكر في كل مسألة قدر ما يليق بهذا الكتاب، فأما الإشباع في ذلك فقد سبق في كتابناً المترجم بـ \"تبصرة الأدلة\"، وكتابنا الموسوم بـ \"إيضاح الحجة\" ليكون العقل حجة بحمد الله ومنه."], [85, "فصل في الاستطاعة مع الفعل\r"]], "pg": [82, 85]}, "466.7": {"x": [[85, "الاستطاعة والقدرة والقوة إذا أضيفت إلى العبد يراد بها كلها معنى واحد في مصطلح أهل الأصول، ثم الاستطاعة عندنا قسمان:\rأحدهما: سلامة الأسباب والآلات والجوارح والأعضاء، وهي المعنية يقوله تعالى: {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: 97]. قيل هو الزاد والراحلة، وبقوله: {فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا} [المجادلة: 4]، أي: لم يكن له الآلات السليمة والأسباب الصالحة، وبقوله إخباراً عن أهل النفاق: {لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ} [التوبة: 42]، أي: لو كانت لنا الآلات والأسباب.\rوصحة التكليف تعتمد هذه الاستطاعة؛ إذ العادة جارية أن المكلف لو قصد اكتساب الفعل عند سلامة الأسباب وتوفر الآلات لحصلت له القدرة الحقيقية، وإنما لا يحصل لاشتغاله بضد ما أمر به، فصار مطيعاً لحقيقة القدرة.\rوالثانية: الاستطاعة التي هي حقيقة القدرة، وهي المعنية بقوله: {مَا كَانُوا يَسْتَطِيعُونَ السَّمْعَ} [هود: 20]، ألا يرى أن الله تعالى قد ذمهم بذلك، والذم إنما يلحقهم بانعدام حقيقة القدرة عند وجود الأسباب والآلات لا بانعدام سلامة الأسباب وصحة الآلات؛ لأن انتفاء تلك"], [86, "الاستطاعة لا يكون بتضييعه بل هو في ذلك مجبور فلم يلحقه الذم بالامتناع عن الفعل عند انتفائها، وكذا هي المعنية بقول صاحب موسى عليهما السلام: {إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا (67)} [الكهف: 67، 68]، إذ لو كان المراد بها سلامة الأسباب ولآلات لما عاتبه على ترك الصبر.\rوالاستطاعة الثانية عرض تحدث عندنا مقارنة للفعل، وعند المعتزلة والضرارية وكثير من الكرامية هي سابقة على الفعل، وثبوت هذه الاستطاعة يبطل قول النظام وعلى السواري وأبي بكر الأصم: \"أن لا استطاعة للإنسان\"؛ إذ ليست هي معنى وراء المستطيع بل الإنسان مستطيع بنفسه لا بالاستطاعة؛ لأنا بينا بالدليل ثبوتها وهي عرض والعرض معنى وراء الجسم، والذي يحققه أنا نجد إنساناً سليم الجوارح ليس بذي آفة وهو قادر على خمسين رطلاً ثم وجدناه في حالة أخرى قادراً على حمل مائة رطل من غير زيادة في أجزاء أعضائه. وبهذا"], [87, "يبطل أيضاً قول غيلان وثمامة بن الأشرس وبشر بن المعتر: \"أن الاستطاعة ليست غير سلامة الأسباب وصحة الجوارح وتخليها عن الآفات، وبهذا يبطل أيضاً قول حفص وضرار: \"أنها بعض المستطيع\" لما ثبت أنها عرض، والقول بكون العرض بعض الجسم محال. ثم لا شك في جواز كون الاستطاعة الأولى ــ أعنى أعضاءه السليمة والأسباب الصالحة ــ سابقة على الفعل، وإنما الاختلاف بيننا وبين المعتزلة والكرامية في الاستطاعة الثانية. وشبهتهم أن الاستطاعة لو لم تكن سابقة على الفعل ولم تكن موجودة حال عدم الفعل لكان الأمر بالفعل ولا استطاعة له وقت الأمر ولا حال عدم الفعل تكليف ما ليس في الوسع"], [88, "وهو قبيح، وقد تبرأ الله تعالى عنه بنص كتابه. ألا ترى أن الكافر مأمور بالإيمان ولم يوجد منه الإيمان؟ فلو كانت له قدرة الإيمان لكانت سابقة على الإيمان موجودة بدونه، وثبت ما قلنا، ولو لم تكن القدرة موجودة لكان الكافر مكلفاً بما ليست له القدرة وهو تكليف الأعمى النظر سواءً، وبطلان ذلك متقرر في العقول، والتبري عن ذلك ثابت من الله تعالى بنص كتاب الله تعالى، والذي يؤيد هذا: أن القدرة إنما تكون ليحصل بها الفعل، ولو كانت مقارنة للفعل لما كان حصول الفعل بالقدرة أولى من حصول القدرة بالفعل، والقول به محال، وأهل الحق يقولون: \"إن الاستطاعة التي يحصل بها الفعل عرض، ولا بقاء للأعراض؛ لأن البقاء في الباقي معنى زائد على الذات بدليل وجود الذات في أول أحوال وجوده، ولا بقاء له بل يوصف بالبقاء في الثاني من زمان وجوده؛ ولهذا لم يعد القائل: \"وجد ولم يبق\" مناقضاً، والأعراض ليست بمحل لقيام معنى وراها بها، فاستحال لهذا بقاؤها، وقد ساعدنا على القول باستحالة بقاء الأعراض أبو القاسم الكعبي وأحمد بن على الشطوي وأبو حفص"], [89, "الصيمري، ومن خالفنا فيه من البصرية فقد أقمنا عليهم الدلالة استحالة بقاء الأعراض بما ذكرنا من كون البقاء معنى وراء الباقي، وإذا ثبت ذلك وعرف أن الاستطاعة ليست بباقية، فلو كانت سابقة على الفعل كانت منعدمة وقت وجود الفعل لاستحالة بقائها، فيحصل الفعل بلا قدرة، فصار حصول الفعل في حال وجود القدرة مستحيلاً والفاعل فيها قادرٌ، وحصوله بعد انعدام القدرة واجباً والفاعل فيها غير قادر، ومن زعم بوجوب وجود الفعل ممن لا قدرة له، واستحالة وجوده من القادر، فهو عديم الحظ من العلم والعقل.\rيحققه أن الفعل لما كان يستحيل وجوده وقت وجود القدرة لو كان مأموراً به وقت وجود القدرة لكان هذا تكليف المحال، ولو كان به مكلفاً في ذلك الزمان فهو تكليف ما لا قدرة له عليه، ولو كان به مكلفاً في ذلك الزمان فهو تكليف ما لا قدرة له عليه، ولو لم يكن مكلفاً لارتفع التكليف أصلاً؛ إذ لم تكن مكلفاً لا زمان وحصول الفعل ولا زمان ثبوت القدرة على ما قررنا، وبطل بذلك الأمر والنهي، وزال الوجوب والحظر، وانعدمت الطاعة والمعصية، واضمحل الثواب والعقاب. والقول بذلك خروج عن الدين، ورفع للشرائع بأسرها، وهو كفر محض. ثم العجب من قوم يقولون: \"إن القائل بأن العبد كلف بتحصيل فعل له عليه القدرة وقت حصوله قائل بتكليف ما لا يطاق\"، والقائل بأن العبد كلف تحصيل"], [90, "فعل لا قدرة له عليه وقت الفعل ولو لم يكن هذا حماقة أو وقاحة فلا وجود لهما في الدنيا، والله تعالى الموفق.\rثم نقول: القدرة لما كانت عند الفعل منعدمة لم يكن في وجودها قبله فائدة، ولا أثر لوجودها قبله في حصوله إذا كانت لدى حصوله منعدمة كالآلة؛ فإن اليد لو انعدمت لا تصور لحصول البطش بها وإن كانت قبل ذلك موجودة، فكذا هذا، ومن جوز حصول الفعل بعد انعدام القدرة يلزمه أن يجوز حصول البطش بعد انعدام اليد، وكذا هذا في كل آلة وسببٍ، وحيث كان ذلك تجاهلاً ودخولاً في السوفسطائية فكذا هذا، وجاء من هذا أن كل فعل وجد عندهم وجد بلا قدرة، ولا أثر لها في حصوله، فكانت القدرة مما لا منفعة في وجوده ولا طائل تحته، وكل من هذا قوله فهو القائل بتكليف ما لا يطاق الرافع الشرائع، المبطل للحظر والوجوب، الرافع للثواب والعقاب. وقول من جوز فهم بقاء القدرة ويقول: \"هي موجودة قبل الفعل ومعه\" باطل لما مر من استحالة القول ببقائها، ثم نقول: هل يصح وجود الفعل بها في الحالة بها في الحالة الأولى؟ فإن قالوا: \"نعم\"، فقد تركوا مذهبهم وانقادوا للحق حيث جوزوا مقارنة الفعل، وإن قالوا: \"لا\"، قلنا: إذا كان يستحيل وجود الفعل بها في الحالة الأولى وهي في الحالة الثانية كذلك لم يتغير ولم يحدث فيها معنى لاستحالة ذلك على الأعراض، فلم صار الفعل بها في الحالة الثانية واجب الوجود وهي عين ما كان الفعل به قبل هذه الحالة الثانية واجب الوجود وهي عين ما كان الفعل به قبل هذه الحالة ممتنع الوجود؟"], [91, "وهل هذا إلا القول بوجوب شيء بما يستحيل وجوده به؟ ولا خفاء ببطلانه على أحد، ولو أن قائلاً قال: الفعل يستحيل وجوده بالعجز في حالٍ ثم يجب وجوده به في الثاني كان بطلان قوله ظاهراً، فكذا كذا.\rيحققه أن حصول الفعل في الحالة الأولى لما كان محالاً لكان هو عجزاً؛ إذ ما يستحيل حصول الفعل به يكون عجزاً لا قدرة، ثم القول بوجوب الحصول بعينه في الثاني محال، وبالله العصمة.\rوما زعموا من تكليف ما لا يطاق قد بينا أنهم هم الذين يقولون به لا نحنن ثم نقولك لما كانت الأسباب ثابتة والآلات متوفرة كان بقاء القدرة على العدم لاشتغاله بضد ما أمر به، فصار هو المضيع للقدرة فلم يكن معذوراً، وكان التكليف صحيحاً؛ إذ لو قصد تحصيله لحصلت له القدرة. فأما عند سلامة الأسباب فذاك مما لا يحصل فيه القدرة لدى قصده مباشرة الفعل، فكان ذلك ممنوع القدرة، فلم يكلف الفعل، والله الموفق.\rعلى أن قول أبي حنيفة ــ رحمه الله ــ: \"القدرة الواحد وتصلح للضدين\"؛ فكان المباشر لضد المأمور به شاغلاً للقدرة الصالحة لتحصيل المأمور به بغيره، فكان معاتباً، فكان تكليفه تكليف من هو قادر، والله تعالى الموفق."], [92, "وما تزعمون أن الفعل مع القدرة لو حصلاً معاً لم يكن إضافة حصول الفعل إلى القدرة أولى من إضافة حصول القدرة إلى الفعل. قلنا: ولو كان الاتصاف بكون المحل أسود مع قيام السواد به حصلاً معاً لم يكن إضافة الاتصاف إلى قيام السواد به أولى من إضافة قيام السواد به إلى ثبوت الاتصاف، وحيث كان هذا باطلاً وعلم بالعقل حصول الاتصاف بكون المحل أسود لقيام السواد به لا على القلب علم أن هذا كلام مبني على الخيال، وكذا هذا في كل علةٍ مع معلولها، والله تعالى الموفق."], [93, "فصل في إثبات خلق أفعال العباد\r"]], "pg": [85, 93]}, "466.8": {"x": [[93, "وإذا فرغنا من إثبات الاستطاعة وكونها مقارنة للفعل لا سابقة عليه، فبعد ذلك نتكلم في أفعال الخلق فنقول:\rاختلف الناس في الأفعال الاختيارية للخلق، فزعمت المعتزلة ــ لعنهم الله ــ أن تدبير الله تعالى عنها منقطع، والخلق هم الذين يتولون إخراجها من العدم إلى الوجود، وإحداثها وإيجادها واختراعها، إذ معنى هذه الألفاظ كلها الإخراج من العدم إلى الوجود، غير أن أوائلهم ما كانوا يتجاسرون على إثبات اسم الخالق للفاعل، ويساعدون أهل الحق في قولهم: \"أن لا خالق إلا الله\"، وكانوا يسمون الخلائق موجودين محدثين مخترعين إلى أن أبو علي الجبائي، فرأى أن لا فرق بين الإيجاد والتخليق، فسمى العباد خالقين لأفعالهم، ولم يبال من خرق الإجماع."], [94, "وزعمت الجبرية ورئيسهم جهم بن صفوان الترمذي: ان التدبير في أفعال الخلق كلها لله تعالى، وهي كلها اضطرارية لا اختيار للخلق ولا قدرة كحركات المرتعش وحركات العروق النابضة، وإضافتها إلى الخلق مجاز، وهي على حسب ما يضاف الشيء إلى محله دون ما يضاف إلى محصله، فكان قولنا: \"جاء زيد، وذهب عمرو، وتكلم عبد الله\" بمنزلة قولنا: \"طال الغلام، ومات زيد، وأبيض الشعر\"!!\rوقال أهل الحق: للخلق أفعال بها صاروا عصاة مطيعين، وهي مخلوقة لله تعالى، فيتعلق الثواب والعقاب بفعلهم دون تخليق الله تعالى.\rومذهب الجبرية باطل بدليل الكتاب، وهو قوله تعالى: {اعْمَلُوا مَا شِئْتُمْ} [فصلت: 40]، وقوله: {وَافْعَلُوا الْخَيْرَ} [الحج: 77]، وقوله: {جَزَاءً بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 17].\rاثبت لهم أسماء العمال، ولفعلهم اسم الفاعل، وأمر بذلك ونهى، وقابله بالوعد والوعيد، ومحال المر بم لا فعل للمأمور، والنهي عما لا فعل للمنهي، ثم إن من الأفعال ما هو طاعة، ومنها ما هو معصية، ويثاب المطيع ويعاقب العاصي، ولو ذلك كله من الله تعالى لا فعل"], [95, "للعبد البتة لكان الله تعالى هو المطيع العاصي المثاب المعاقب المجزي بصنعه، وذلك كله كفر وضلال، وكذا بعيد في العقل محال أن يأمر أحد نفسه وينهاها، ويثيبها ويعاقبها، وكذا محال أن يكون الله تعالى سفيهاً جائزاً ظالماً وقد سمى الله تعالى بذلك الذين نهاهم، فلو كان الفعل منه والنهي له لكان الموصوف بذلك كله هو الله تعالى، والقول به كفر. ثم إن كل أحد بطريق الضرورة الفرق بين ما هو مختار وله فيه صنع وبين ما هو فيه مضطر، فمن سوى بين الأمرين فقد عرف بطلان قوله بالضرورة على أنه لا معنى لاشتغال من هذا قوله بمناظرة خصومه؛ إذ هي بكون القول ولا قول له، بل الله تعالى هو الذي يناظر، ويسأل، ويجيب، ولا صنع للعبد فيه وبطلان هذا الثابت في البداية، وإذا كان المر كذلك لا معنى لإطالة الكتاب بالاشتغال بمحاجتهم مع أن أهل هذه المقالة قد انقرضوا عن آخرهم، وكفينا مؤنة مجادلتهم، وبالله العصمة والتوفيق.\rوالمعتزلة يتعلقون بالأمر والنهي، والوعد والوعيد، والثواب والعقاب، ويقولون: \"لو كان الله تعالى هو الذي تولى تخليق أفعال الخلق لصار هو المأمور النهي المثاب المعاقب، ولكان هو المطيع العاصي، الذم والحمد على أفعال الخلق ينبغي أن يكونا عائدين عليه إذ هو الموجد لهما\"، وكذا يقولون: \"لو كان الله تعالى هو الذي تولى تخليق أفعال الخلق لصار هو المأمور المنهي المثاب المعاقب، ولكان هو المطيع العاصي، وكذا الذم والحمد على أفعال الخلق ينبغي أن يكونا عائدين إليه إذ هو الموجد لهما\"، وكذا يقولون: \"دخول مقدرو واحد تحت قدرة قادرين محال اعتباراً بالشاهد الذي هو دليل الغائب، فلو كان أفعال الخلق داخلة تحت"], [96, "قدرة الباري لاستحال دخولها قدرة الخلق، والجبر باطل عرف بطلانه بالضرورة، وبما ذكرتم من الدلائل، وضح مذهب الجبرية، ولو كانت داخلة تحت قدرة الخلق لاستحال دخولها تحت القدرة الله تعالى، والجبر باطل عرف بطلانه بالضرورة، وبما ذكرتم من الدلائل، فصح ما ذهبنا إليه. يحققه أن تعلق الفعل بقدرة قادرين وحصوله بهما يؤدي إلى اشتراك القادرين في الفعل، فكان فيما ذهبتم إليه إثبات الشركاء لله تعالى، وكذا من أفعال الخلق ما هو قبيح وسفه، وإيجاد القبيح، وموجد السفه سفيه، إذ الإيجاد فوق الاكتساب، فمكتسبه سفيه فموجده أولى، على أن الوجود إذا كان بالله تعالى وليس وراء الوجود معنى يعقل ليتعلق بقدرة الخلق صارت الأفعال كلها حاصلة بالجبر.\rوأهل الحق يتعلقون بقوله تعالى: {اللَّهُ خَالِقُ كُلِّ شَيْءٍ} [الرعد: 16]، والآية خارجة مخرج التمدح، ولا تمدح إلا بما لا يساويه فيه غيره، وفي إخراج فعل غيره عن تخليقه إزالة التمدح؛ لأنه يصير في التقدير كأنه قال: \"خالق كل شيء ليس بفعل لغيره\"، ويساويه في هذا عندهم كل ما درج ودب، وهذا باطل، وبالله التوفيق.\rوبقوله تعالى: {وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] أي: وعملكم، كقوله: {جَزَاءً بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 17]، والله الموفق."], [97, "والمعقول لنا: أن إثبات قدرة التخليق للعبد محال؛ لأن من شرط قدرة التخليق ثبوت العلم للخالق بالمخلوق بدليل قوله تعالى: {أَلَا يَعْلَمُ مَنْ خَلَقَ} [الملك: 14]، وكذا بداية العقول واعتراف الخصوم باشتراط العلم يدلان على هذا. ثم الخلق لا علم لهم بكيفية الاختراع من العدم إلى الوجود، وكذا لا علم لهم بما يخرج عليه فعلهم من المقادير والأحوال؛ إذ لا علم لأحد بقدر ما يقطع بفعله من أجزاء الهواء والمكان، وبقدر ما يشغله من الزمان، وبقدر ما يفعله من صفتي القبح والحسن، بل يوجد الكفر وعبادة غير الله تعالى على صفة القبح ويظنه الكافر حسناً، وعند فوت شرط قدرة التخليق لا وجه لإثباتها، وكذا من خاصية التخليق أن الفعل يخرج على حسب إرادة الخالق، ثم إرادة الكافر أن يخرج كفره حسناً، وإرادة الماشي أن يوجد مشيه غير متعب ولا مؤذٍ، ولم يوجدا على حسب مرادهما؛ فدل أن الفعل ما وجد بقدرتهما وإيجادهما، ولا وجه إلى القول بالوجود إلا بموجد لما فيه تعطيل الصانع؛ فدل أن الفعل وجد بإيجاد الله تعالى. يحققه أن إثبات قدرة التخليق للعباد يؤدي إلى تعجيز الصانع أو منعه عن الفعل، فإنه تعالى قادر على أن يخلق في يد زيد حركة، ولو خلق زيد فيها سكوناً لن يبق لله تعالى قدرة تخليق الحركة لما فيه من الإحالة، فكانت قدرته ثابتة بشرط أن لا يعجزه العبد عن ذلك بتخليقه السكون ولا يمنعه، وهو محال، وفي هذا أيضاً إبطال دلالة"], [98, "التمانع والعجز عن إثبات التوحيد؛ إذ لما كان للعبد أن يوجد فعلاً ويعجز الله تعالى عن ذلك أو يمنعه عن تحصيل ما كانت له عليه القدرة ومع ذلك لم تبطل ألوهيته، فكذا إذا عجزه شريكه أو منعه، ولأن العالم أعراض وأعيان، والله تعالى يتولى تخليق الأعيان، وتخليق بعض الأعراض عند جمهورهم سوى معمر، فإنه زعم أن لا قدرة لله تعالى على تخليق عرض ما البتة، بل محالها هي التي خلقها، بعضها بطريق الاختيار، وبعضها بطريق الاضطرار.\rثم لو كان للعباد قدرة تخليق أفعالهم وهي أعراض لكان بعض العالم حاصلاً بإيجاد الله تعالى، ويعضه بإيجاد غيره، وهو إثبات الشركة لغير الله تعالى مع الله تعالى في إيجاد العالم كما فعل المجوس، بل المجوس أسعد حالاً منهم، فإن عندهم ليس لله تعالى إلا شريك واحد، وعند المعتزلة لله تعالى شركاء في تخليق العالم لا يحصون كثرة؛ إذ"], [99, "كل من له فعل اختياري من أنواع الحيوانات فهو خالق مع الله تعالى، وكذا المجوس ينفون عنه القبائح لا غير، والمعتزلة ينفون عنه القدرة التخليق لكل ما هو في نفسه حسن كالطاعات، بل يفضلون غير الله تعالى على الله تعالى؛ إذ حسن ما يوجده الله تعالى وتخليقه طبيعي، وحسن ما يخلقه العباد عقلي، والحسن العقلي حقيقي دون الحسن الطبيعي، وتفاضل الفاعلين بتفاضل أفعالهم، ولقد صدق رسو الله صلى الله عليه وسلم حيث قال: \"القدرية مجوس هذه الأمة\"، والله الموفق.\rيحققه أن أفعال العباد لو كانت مخلوقة لهم ولو كانت قدرة الله تعالى عنها منتفية لكانت القدرة عندهم من صفات الفعل؛ إذ ما ينتفي ويثبت ويخص ويعم فهو عندهم صفة فعل، فلا يكون موصوفاً به عندهم، وهذا هدم قواعدهم، وإثبات التناقض حيث زعموا أن الله تعالى قادر لذاته، وكان في الأزل قادراً، وبالله العصمة.\rيحققه أنه لو كان العبد خالقاً لفعله لوقع التشابه بين فعله وفعل الله تعالى، إذ كل واحد منهما إخراج من العدم إلى الوجود، والإخراج والمخرج والإيجاد والموجود عندهم واحد، والله سبحانه وتعالى نفى ذلك بقوله تعالى: {أَمْ جَعَلُوا لِلَّهِ شُرَكَاءَ خَلَقُوا كَخَلْقِهِ} [الرعد: 16]، والمعتزلة يثبتون ما نفاه الله تعالى، وفيه ما فيه من تخطئة الله تعالى، ونسبته إلى الخطأ، وبالله العصمة."], [100, "وإذا ثبت ما ذكرناه استحال ثبوت قدرة التخليق للعبد، وثبت بالضرورة التي يصير دافعها مكابراً، وبما ذكرنا من الدلائل السمعية والعقلية على الجبرية أن العبد له فعل حصل بمجموع الدليلين أن العبد له فعل ليس هو خالقاً له، ولم يصر العبد بخلق الله تعالى غياه مضطراً كما لا يصير بعلم الله تعالى لما أنه تعالى خلق فعله الاختياري فلم يصر ضرورياً، كما علم بفعله الاختياري فلم يصر ضرورياً، وثبت بمجموع الدلائل أن دخول مقدور واحد تحت قدرة قادرين أحدهما قدرة الاختراع والأخرى هي قدرة الاكتساب جائز، وإنما الممتنع دخولها تحت قدرة قادرين كل واحد منهما قدرة الاختراع، واعتبارهم بالشاهد فاسد لما أن لا قدرة في الشاهد لأحد على ما هو خارج عن محل قدرته، فلم يتصور دخول مقدور تحت قدرة قادرين لهذا، وفي الغائب الأمر بخلافه، واعتبار الغائب الشاهد من غير إثبات دليل التسوية بينهما فاسد، فعند قيام دليل التفرقة أولى أن يكون فاسداً.\rيحققه أن الله تعالى هو الذي يعطي القدرة للعبد، ومن لا قدرة له على فعل يستحيل منه إقداره غيره عليه، كمن لا علم له بشيء يستحيل منه إثبات العلم لغيره به، وإذا كان هذا معقولاً والله تعالى هو المقدر للعبد"], [101, "كانت قدرته أيضاً ثابتة، فكان الفعل مقدور القادرين ضرورة، والله تعالى الموفق.\rوما يزعمون من إثبات الشركة فذاك كلام صدر عن جهلهم بالشركة، فإن الشركة أن يتفرد كل شريك بما هو له دون شريكه، كشركاء القرية والمحلة، وكما يفعله المجوس، فإن ما هو لأحد الشريكين لم يكن للآخر بوجه من الوجوه. وهو غير ما يقوله المعتزلة لا ما نقوله نحن، فإن ثبوت شيء مضافاً إلى ذاتين، إلى كل منهما بجهة لا نعرف شركه، فإن الله تعالى ملك العباد أشياء وتلك الأشياء ملك لله تعالى ملك تخليق، ولم يكن العباد شركاء الله تعالى في الأملاك لما أن ما هو ملك الله تعالى بالتخليق عينه ملك العبد لثبوت التصرف فيه، ولم يكن الله تعالى مختصاً بملك شيء والعبد بملك آخر لتثبت الشركة كما هو في حق شركاء القرية، فكذا ما نحن فيه، وتبين أنهم هم المثبتون لله تعالى شركاء في العالم لا خصومهم، والله الموفق.\rوما يزعمون أن من أفعال العباد ما هو قبيح وإيجاد القبيح قبيح، قلنا: ومن أفعالهم ما هو حسن، فما جوابكم فيه؟\rثم نقول: لما بينا بالدليل أن ليست للعبد قدرة الإيجاد، ولا موجد للفعل إلا الله تعالى، وثبت أن الله تعالى حكيم ليس بسفيه، ثبت أن إيجاد"], [102, "القبيح ليس بقبيح، وأنه حكمة، غير أنكم جاهلون بحقيقة الحكمة والسفه، وتلقيتم ما تلقيتم من إخوانك المجوس والثنوية. ثم نقول: \"الحكمة: ما له عاقبة حميدة\"، \"والسفه: ما ليس له عاقبة حميدة\"، فلم قلتم: إن ليس لتخليق الكفر عاقبة حميدة؟ وبم عرفتم خلوه عنها؟ لأجل أنكم لم تقفوا على ما فيه من جهة الحكمة، وما لا تقفون عليه لا يكون حكمة!! فإن قالوا: \"نعم\"، بأن عنادهم أو وقوفهم بعقولهم على كثير من الحكم البشرية فضلاً عن الحكم الربوبية، وإن قالوا: \"من الجائز أن لا يكون حكمة لا نقف عليها\"، قلنا: ولم أنكرتم أن يكون لله تعالى في تخليق الكفر والمعاصي حكمة قصرت عنها عقولكم الضعيفة؟ ثم نقول ـــ متبرعين: إن الله تعالى في تخليق الكفر والمعاصي حكماً لا يحيط بها الأخصاء، ولا يبلغها لكنه الاستقصاء، منها: أن تخليقه ما هو حسن من الأفعال وقبيح منها يستدل على كمال قدرته ونفاذ مشيئته، حيث قدر على تخليق المتضادين وإيجاد المتقابلين، وهو آية كمال القدرة؛ إذ من يوجد منه نوع واحد لا غير كان مضطراً؛ ولهذا كان تخليق ما حسن من الأجسام وقبح، وطاب وخبثن ونفع وضر، وآلم وألذ، حكمة بالغة وتدبيراً صائباً، فكذا هذا في الأفعال والأعراض.\rوفيه أيضاً: إظهار القدرة على فعل الغير، وبه تمتاز القدرة الأزلية من القدرة الحديثة، والمشيئة الشاملة من المشيئة القاصرة، فيظهر"], [103, "بذلك أنه قادر على محل قدرة غيره، متصرف في مقدور عباده، مستبد في تحصيل مراده وغيره مفتقر إليه محتاج إلى إعانته، والله الموفق.\rومنها: أنه تعالى بتخليقه الأفعال كلها خيرها وشرها وحسنها وقبيحها بين أنه يفعل ما لا يفعل لا عن حاجة ولا لجلب نفع أو دفع مضرة، إذ من ذلك فعله لا يفعل إلا ما ينتفع به.\rومنها: أن بذلك يظهر أنه تعالى غنى عن خلقه، عزيز بذاته لا يتعزز بكثرة أوليائه وأتباعه، ولا يتقوى بأعوانه وأنصاره، ولا يضعف بكثرة أعدائه، ولا يتضرر بتوفر عصاته، بل هو العزيز في ذاته المنيع في سلطانه القوي أيده المتين كيده. ووراء هذه حكمة ذكرها أئمة أهل الكلام لا وجه لإطالة الكتاب بذكرها عند حصول الغنية عنها بما ذكرت منها. ثم لما كان إيجاد ما خبث من الأجسام حكمة لما تعلقت به العاقبة الحميدة، فكذا إيجاد ما قبح من الأفعال، على أنا لا نقول على الإطلاق أن خلق الكفر، بل نقول: \"خلق الكفر قبيحاً باطلاً شراً فاسداً\"، والحكمة تقتضي كون الكفر على هذه الصفات، فإيجاده عليها كان حكمة، وإنما السفه تحصيله حكمة حسنا صواباً كما يقصده الكافر، والله الموفق.\rوهذا يبطل قولهم: \"إنه تعالى لو كان هو الذي تولى إيجاد الكفر لجاز ذمه عليه\"، لأن الإيجاد فوق الاكتساب، فإن استحقاق الذم بفعل السفه لا بفعل الحكمة، وقد مر أن الله تعالى في إيجاده حكيم، والعبد في اكتسابه سفيه، لا بفعل الحكمة، وقد مر أن الله تعالى في إيجاده حكيم، والعبد في اكتسابه سفيه، لما له في حقه من وخيم العاقبة، ولما يقصد تحصيله على"], [104, "ضد ما تقتضيه الحكمة من الصفات، فيستحق العبد المذمة دون الله تعالى، بل هو المستحق لكل حمد على ما قررنا، والله الموفق.\rوما زعموا أن ليس وراء الوجود معنى يتعلق به القدرة، قلنا: مجموع ما ذكرنا من الدليلين أن العبد له فعل وليست له قدرة التخليق يبطل هذا الكلام، ولا حاجة بنا إلى بيان الجهة التي يتعلق بها قدرة العبد بل بنا الحاجة إلى إثبات أنه ليس بمجبور، وأنه فاعل عن اختيارٍ، وأنه ليس بمخترع، وقد فرغنا عن ذلك كله بحمد الله تعالى.\rثم لما ثبت أن الإيجاد ليس من قبل العبد، وأن له فعلاً فيتعلق بما هو فعله الثواب والعقاب، والوعد والوعيد، والأمر والنهي، والحمد والذم، وإن كان ذلك غير متعلق بالإيجاد، على أن عندنا الموجد بإيجاد الله تعالى باختيار العبد هو فعل العبد، وليس بفعل الله تعالى بل هو مفعوله، وهذه المعاني متعلقة بمفعوله لا بفعله الذي هو الإيجاد، والله الموفق.\rثم إن مذهب جمهور المعتزلة: \"أن المعدوم شيء\"، وأكثرهم يزعمون أنه عرض، وكذا هو ذات وحركة، والشيء شيء لنفسه، والموجود موجود لنفسه، والقدرة متعلقة بالوجود دون الشيئية، وإن كان كل منهما راجعاً إلى الذات، وتعلق القدرة بالوجود لا يوجب تعلقها بالشيئية، ولا بالعرضية، ولا بالذاتية، ولا بكونه حركة، وإن لم يكن الوجود معنى وراءها، كذا قدرة الصانع جل وعلا متعلقة بالوجود لا غير، ولا تعلق لها بالجوهرية ولا بالشيئية ولا بالعرضية، وانعدام التعلق بهذه الوجوه لم يمنع من تعلقها بالوجود، وإن كان الوجود راجعاً إلى"], [105, "الذات وليس وراء الذات، فإذا قالوا بمثل ما قلنا في حق أفعال العباد فإنا لا نأبى إلا تعلق قدرة العبد بالشيئية والعرضية متعلقة بقدرة الله تعالى، وهم أبوا ذلك، وفيه تعطيل الصانع، والقول بقدم العالم، ثم لا فرق في حق العبد إذا لم تكن قدرته متعلقة بالشيئية بين أن تكون الشيئية ثابتة بقدرته، وبهذا يتبين بجواز مذهب المعتزلة وتناقض أصولهم الفاسدة، وكذا عندهم الثواب والعقاب والمر والنهي والحمد والذم متعلقة بالوجود لا بالشيئية والعرضية، وهو غير ما يذهب إليه خصومهم، بل ما يذهبون إليه اتباع للدلائل العقلية والسمعية، وانقياد لها، واعترف بحدوث العالم من جميع الوجوه، وثبوت الصانع و وحدانيته. وهم يقولون بعين ما يقوله الخصوم في المتنازع فيه مع القول بما يؤدي إلى القول بقدم العالم وتعطيل الصانع ــ عصمنا الله من كل قول هذا عقباه.\rثم إن عبارات أصحابنا اختلفت في الفرق بين الخلق والكسب، فقال: بعضهم: \"كل مقدور وقع في محل قدرته فهو كسب، وما وقع لا في محل قدرته فهو خلق، واسم الفعل يشملها\"، وقيل: \"ما وقع بآلة فهو كسب، وما وقع لا بآلة فهو خلق\"، وقيل: ما وقع المقدور به من حيث"], [106, "يصح انفراد القادر به فهو خلق، وما وقع مقدور به مع تعدد انفراد القادر به فهو كسب\"، والله الموفق.\rوهذه المسألة عظيمة يكثر بها دلائل أهل الحق وشبهات الخصوم، وفي هذا القدر كفاية لمن لم يكن همه التعنت والتعصب والميل إلى الهوى، والله تعالى الموفق."], [107, "فصل في أن المتولدات مخلوقة لله تعالى\r"]], "pg": [93, 107]}, "466.9": {"x": [[107, "وإذا ثبت أن العبد ليست له قدرة الاختراع ثبت أن ما يوجد من الم في المضروب عقيب ضرب الإنسان، والانكسار في الزجاجة عقيب كسر إنسان، أو من الحركة في الخشبة عقيب اعتماد الرجل عليها، كل ذلك مخلوق الله تعالى، ولا صنع للعبد فيه؛ لانعدام قدرة التخليق، واستحالة اكتساب ما ليس بقائم بمحل قدرته، وبطل قول المعتزلة: إن هذه الأشياء متولدة من فعل العبد، وهي فعله مخلوقة من قبله، وهو خالقها!!\rوبطل قول بشر بن المعتمر أحد رؤسائهم: إن السمع والبصر وما وراءهما من الإدراكات، وجميع الألوان والطعوم والروائح متولدة من فعل الإنسان مخلوقة له مخترعة من جهته!! والذي يوجب بطلان قول المعتزلة: إن الألم لو كان فعلاً لفاعل سببه وهو الضرب لكان لا يخلو إما: أن فعله بالقدرة التي حصل بها الضرب، وإما: أن فعل بقدرة أخرى. وكل ذلك باطل لانعدام التمكن من الامتناع عن حصول الألم بعدما وجد منه الفعل قبل حصول المتولد، والقادر متمكن من الامتناع وتحصيل ضده قبل حصول الفعل، وكذا الأم لم يوجد بعد موت الجارح"], [108, "وبقاء قدرته بعد موته، أو حدوث قدرة له بعد موته محال، ولا فعل بدون القدرة؛ فدل أنه ليس بفعل له.\rوقول ثمامة بن الأشرس: إن المتولدات أفعال لا فاعل لها إلا الله تعالى ــ كما يقوله أهل الحق ــ ولا فاعل أسبابها ــ كما يقوله إخوانه من المعتزلة ــ قول يوجب تعطيل الصانع لما فيه من تجويز اختصاص ما لم يكن ثم بالوجود بدون تخصيص مخصصٍ.\rوقول النظام: \"إن المتولدات فعل الله تعالى بإيجاب الخلقة، وقول أبي العباس القلانسي: إنه فعل الله تعالى بإيجاب الطبع\"، محال لما أن لا قول بإيجاب الطبع أو الخلقة على الله تعالى شيئاً، وفي الإيجاب جعل من أوجبت عليه مضطراً، والمضطر عاجز، وتجويز العجز والاضطرار على الله تعالى ممتنع، والله تعالى الموفق."], [109, "فصل في أن المقتول ميت بأجله\r"]], "pg": [107, 109]}, "466.10": {"x": [[109, "وبثبوت ما ذكرنا ثبت أن القتل فعل قائم بالقاتل وهو فعل يخلق الله تعالى عقيبه في الحيوان الموت وانزهاق الروح، والموت في مخلوق الله تعالى في الميت لأن الموت من فعل الله تعالى، والقتل من فعل القاتل\"!!، وقول غيره من المعتزلة: \"إن في المقتول معنيين: أحدهما: من الله تعالى وهو الموت، والآخر: من العب وهو القتل\".\rثم المقتول ميت بأجله عندنا بخلاف ما يقوله المعتزلة أنه غير مقتول بأجله، وله أجل آخر؛ لأن الله تعالى لما كان عالماً أنه يقتل جعله أجله، ولا يليق به تعالى أن يجعل له أجلاً يعلم أنه لا يعيش إليه البتة، أو يجعل أجله أحد الأمرين كفعل الجهال بالعواقب!! مع أن القول بأن الله تعالى أعطي العبد قدرة مع الله تعالى عن إبقاء عبده إلى ما جعله أجلاً له وقدره قطع ما جعله أجلاً له محال، ووجوب الضمان أو القصاص على"], [110, "القاتل تعبد لارتكابه المنهي، ومباشرته فير محل قدرته فعلاً أجرى الله تعالى العادة بتخليق الموت عقيبه، والله الموفق."], [111, "فصل في الأرزاق\r"]], "pg": [109, 111]}, "466.11": {"x": [[111, "ومن هذا القبيل قول المعتزلة: \"إن الحرام ليس برزق، والرزق هو الملك والإنسان يقدر أن يتناول ما جعله الله تعالى رزقاً لغيره، ويمنعه عن إيصال ما جعله رزقاً لحيوان آخر إليه!! وهذا باطل بل الحرام وكل يستوي في رزقه حلالاً كان ذلك أو حراماً، ولا يتصور إنسان أن لا يأكل رزقه أو يأكل رزق غيره، والرزق هو الغذاء، فما قدر الله تعالى أن يجعله غذاء لشخص قط لا يصير غذاء لغيرهن وكما أن الإنسان يتغدى به لكان لا يتصور أن يرزق الله تعالى من لا يتصور ثبوت الملك له، ولخرج قول الله تعالى: {وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا} [هود: 6] لغواً ضائعاً، ولا يتفوه به مسلم، وبالله تعالى العصمة."], [112, "فصل في أن المعاصي بإرادة الله تعالى ومشيئته\r"]], "pg": [111, 112]}, "466.12": {"x": [[112, "وإذا ثبت أن الله تعالى هو الذي يتولى تخليق أفعال العباد خيرها وشرها طاعنها ومعصيتها، والله مختار في تخليق ما يخلق غير مضطر فيه، ولا اختيار بدون الإرادة؛ ثبت ما يوجد من أفعال العباد كلها بإرادة الله تعالى، ومل لم يوجد منها لم يكن بإرادة الله تعالى، إذ لم يخلقه. ثم حاصل المذهب: أن كل حادث حدث بإرادة الله تعالى على أي وصف كان. ثم ما كان من ذلك طاعة فهو مشيئة الله تعالى وإرادته، ورضاه ومحبته، وأمره وقضائه وقدره، وليس بأمر الله تعالى، ولا برضاه، ولا بمحبته؛ لأن محبته ورضاه يرجعان إلى كون الشيء عنده مستحسناً، وذلك يليق بالطاعات دون المعاصي.\rوزعم الأشعري أن المحبة والرضا بمعنى الإرادة تعمان كل"], [113, "موجود كما تعم الإرادة.\rثم إن مشايخنا ــ رحمهم الله يقولون تيسيراً على المتعلمين: إن ما علم الله أن يوجد أراد وجوده شراً كان أو خيراً، قبيحاً كان أو حسناً، طاعة كان أو معصية، وما علم الله تعالى أنه لا يكون شراً كان أو خيراً، قبيحاً كان أو حسناً، طاعة كانت أو معصية، فالله تعالى لما علم أن يوجد من فرعون الكفر لا الإيمان أراد منه الكفر لا الإيمان، وكذا من سائر العصاة والكفرة.\rوالمعتزلة يزعمون: أن ما أمر الله تعالى به أراد وجوده وإن علم أنه لا يوجد، وما نهى عنه أراد أن لا يوجد وإن علم وجوده!! فلما أمر فرعون بالإيمان أراد منه الإيمان، ولما نهاه عن الكفر لم يرد منه الكفر!!"], [114, "ثم هذه المسألة هي غير مسألة خلق الأفعال، على ما مر يثبت ما يثبت به تلك المسألة.\rثم إن السلف تكلموا فيها بطريق الأصالة، فتبعهم في ذلك، فنقول: إن المعتزلة يتعلقون بقوله تعالى: {وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ} [الذاريات: 56] أخبر أنه خلقهم ليعبدوه، وعندكم ما خلق الكفرة ليعبدوه، بل ليكفروا به، وهو خلاف النص، والمعقول لهم أن الكفر والمعاصي سفه، ومريد السفه سفيه في الشاهد وكذا في الغائب، وكذات أفعال العباد ما هو شتم الله تعالى والافتراء عليه، ومريد شتم نفسه والمتعرض له سفيه، ولأن الأمر بما لا يريده الآمر سفه، وكذا إرادة ما لا يرضى به، ولأن العبد ما لا يمكنه الخروج عن إرادة الله تعالى عندكم، وفيه جعل العباد مجبورين، وهو باطل.\rولأهل الحق قوله تعالى: {إِنَّمَا نُمْلِي لَهُمْ لِيَزْدَادُوا إِثْمًا} [آل عمران: 178] أخبر أنه أراد بإملائهم ازدياد الإثم، وقوله تعالى: {وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ} [الأعراف: 179]، ومن ذرأه لجهنم أراد منه ما يصير بإدخاله ما ذرئ له عادلاً لا ظالماً، وقوله تعالى: {فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا} [الأنعام: 125] أخبر أنه يريد ضلال بعض، ويجعل ما به يحصل ضلاله وهو ضيق القلب، وقوله تعالى ــ خبراً عن نوح"], [115, "عليه السلام: {وَلَا يَنْفَعُكُمْ نُصْحِي إِنْ أَرَدْتُ أَنْ أَنْصَحَ لَكُمْ إِنْ كَانَ اللَّهُ يُرِيدُ أَنْ يُغْوِيَكُمْ} [هود: 34] أخبر نوح أن الله تعالى يريد أن يغويهم، والمعتزلة يخالفون ويقولون: \"لا يريد أن يغويهم\"!!\rوقوله تعالى: {وَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ} [النحل: 9]، وقوله: {وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَنْ فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا} [يونس: 99]، وعندهم ما شاء إيمان من في الأرض وما آمنوا!! وهو تكذيب الله تعالى في خبره، وهو كفر، وقوله تعالى: {وَلَوْ شَاءَ اللَّهُ مَا أَشْرَكُوا} [الأنعام: 107]، وعندهم شاء، ومع ذلك أشركوا!! ومنه تكذيب الله تعالى في خبره. وفي الآيات كثرة، وفي هذا القدر كفاية.\rوالمعقول أن الله تعالى لو شاء من الكافر الإيمان، والكافر شاء من نفسه الكفر، وكذا إبليس شاء منه الكفر، لكانت مشيئة الكافر ومشيئة إبليس أنفذ من مشيئة الله تعالى، وهو أمارة العجز، وفي تجويز هذا إبطال ما مر من دلالة التمانع، وهو يؤدي إلى تصحيح مذهب الثنوية، وإبطال توحيد الصانع."], [116, "واعتراض المعتزلة على قوله تعالى: {وَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ} [النحل: 9]، وما ذكرنا بعدها من الآيتين: أن المراد من المشيئة المذكورة في الآيات مشيئة الجبر، وبهذا يعترضون على المعقول أن انعدام ما يشاء ووجود ما لا يشاء إنما يدل على الضعف أن لو لم يكن له قدرة إيجاد ما يشاء ودفع ما لا يشاء، وله قدرة إيمان كل كافرٍ جبراً، وقدرة دفع كفر كل كافر جبراً، ومن هذا وصفه لا يوصف بالضعف.\rهذا اعتراض فاسد فإنهم إذا عن سئلوا عن تفسير مشيئة الجبر زعم أبو هذيل العلاف ومن تابعه: أن تفسير ذلك أن يخلق الله تعالى فيهم الإيمان، ويندفع الكفر. وهذا على أصولهم غير مستقيم؛ لأن المؤمن عندهم: فاعل الإيمان، والكافر: فاعل الكفر؛ ولهذا أبوا أن يكون الله تعالى خالقاً لأفعال الخلق؛ إذ لو فعل لكان هو الكافر العاصي!! فعلى هذا لو خلق إيمانهم لكان هو المؤمن لا الكفرة، وهو تعالى أراد إيمانهم لا إيمان نفسه، فلم ينفذ بهذا مشيئته، ولصار بذلك الإيمان هادياً نفسه مؤتياً نفسه إيمانها لا كل نفس."], [117, "وزعم الجبائي: أن تفسير مشيئة الجبر أن يخلق فيهم علماً ضرورياً لصحة الإيمان، فيؤمن حينئذٍ. وهذا أيضاً فاسد؛ لأن العلم غير الإيمان، ووجود أحد المتغايرين لا يوجب وجود الآخر لا محالة. يحققه: أن أهل العناد كانوا يعرفونه كما يعرفون أبناءهم ولم يؤمنوا، وقال الله تعالى: {وَإِنْ يَرَوْا كُلَّ آيَةٍ لَا يُؤْمِنُوا بِهَا} [الأنعام: 25]. قال: {وَلَوْ أَنَّنَا نَزَّلْنَا إِلَيْهِمُ الْمَلَائِكَةَ} إلى قوله: {مَا كَانُوا لِيُؤْمِنُوا} [الأنعام: 111].\rوزعم ابنه أبو هاشم: أن معنى مشيئة الجبر أن يخلق الله تعالى له العلم الضروري أنه لو لم يؤمن يعذب عذاباً شديداً. وهو أيضاً باطل؛ لأن أهل العناد كانوا يعملون أنهم لو لم يؤمنوا لخلدوا في النار، ومع ذلك لم يؤمنوا. ثم عندهم: أن الله تعالى قادر على الظلم والكذب والسفه، ولو فعل شيئاً منه لبطلت ألوهيته، وزوال الربوبية ضرر عظيم. فعلى تأويله يكون الله تعالى مجبوراً على العدل والصدق والحكمة. وهذا كفر صريح. ونقول: إن مشيئة الله تعالى أن يوجد منهم إيمان اختياري يستحقون به الثواب، ويندفع به عنهم العذاب، والإيمان الحاصل جبراً غير ما هو المراد، فدل أن الحجة بالآيات والمعقول لازمة، والاعتراض على ذلك كله باطل، وبالله المعونة. يحققه: أن الأمة بأسرهم يقولون: \"ما شاء الله تعالى كان، وما لم يشأ لم يكن\"، وهذا إجماع منهم على صحة ما"], [118, "ذهبنا إليه، وبطلان قول المعتزلة، وهذا الكلام لا يحتمل تأويل مشيئة الجبر، فإنه إن استقام في أحد شطريه وهو قولهم: \"ما شاء الله كان\"، لم يستقم في الشطر الآخر وهو قولهم: \"وما لم يشأ لم يكن\"؛ لأنه لم يشأ الأفعال الاختيارية التي هي الطاعات جبراً، ومع ذلك كانت، والله تعالى الموفق.\rوالذي يؤيد ما ذهبنا إليه أن الله تعالى لما عرف من فرعون أنه يكفر ولا يؤمن، فلو أراد منه أن يؤمن ما ذهبنا إليه حصل لصار هو جاهلاً، فيصير مرتداً بتجهيل نفسه، وزوال ربوبيته، وكذا أخبر أنه يملأ من جهنم من الجنة والناس أجمعين، ولو أراد منهم الإيمان دون لأراد أن لا يتحقق خبره، ويكون به كاذباً، أو أراد ما يصير بتحقق إخباره ظالماً، فصار مريداً جهل نفسه وكذبه وظلمه، وهو كله سفه، ولا يعترض على هذا بالأمر بالإيمان والنهي عن الكفر. وفيه أيضاً أملا بتجهيل نفسه ونهى عن تصديقه؛ لأنا نقول: الأمر والنهي كل واحد منهما لتحقيق علمه؛ لأنه ما أمر الكافر بالإيمان ليؤمن، وما نهى عن الكفر لينتهي، بل ليجب الإيمان، ويحرم الكفر، فيترك الإيمان الواجب، ويقدم على الكفر المنهي؛ فيستحق بذلك العقاب، فتحقق علمه أنه يترك الإيمان الواجب، ويرتكب الكفر المحذور؛ ويصير بذلك أهلاً للتخليد في النار فيتحقق علمه وإخباره. فإذا كل ذلك لتحقيق علمه وخبره، وإن جهلت المعتزلة ذلك، والله الموفق."], [119, "ولا تعلق لهم بقوله تعالى: {وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ} [الذاريات: 56]؛ لأن أهل التأويل قالوا: \"إلا ليكونوا عباداً لي\"، وهم كانوا عباداً له. يؤيد هذا التأويل: أن على هذا التأويل: أن على هذا التأويل يمكن إجراء الآية على العموم، ولو حملت على العبادة الاختيارية لما أمكن ذلك لخروج الصغار والمجانين عن عمومها؛ لأنهم لم يخلقوا للعبادة.\rوقال كثير من أهل التأويل: قوله: {إِلَّا لِيَعْبُدُونِ} [الذاريات: 56]، أي: إلا أمرهم بالعبادة. وعلى هذا التأويل لا تعلق لهم بها، على أنا نقول: خص الصبيان والمجانين عن الآية. فيخص المتنازع فيه بما ذكرنا من الدلائل، وبقيت الآية محمولة على من علم منهم الإيمان والعبادة.\rوشبهتهم المعقولة أن مريد السفه فاسد؛ لأن السفيه من ليس لفعله عاقبة حميدة. وإذا كان لإرادة السفيه عاقبة حميدة وهي تحقيق العلم والخبر كانت حكمة.\rومريد شتم نفسه إنما يكون سفيها لأنه يلحق به عار الشتم؛ لأنه لم يقم دلالة براءته عما شتم به، فلا يلحق به عار، بل يلحق عار الكذب بشاتمه الذي هو عدوه، وإرادة إلحاق العار بعدوه حكمة، وليست بسفه، فمن قاس مريد إلحاق العار بنفسه في جعلهما سفيهين فهو جاهل بالمقايسة.\rوشبهتهم الثانية فاسدة أيضاً لما مر أن الأمر بما لا يريده ليجب عليه، فيتحقق به علمه، وإرادته حكمة."], [120, "يحققه: أن من يلام على عقوبة عبده فيعتذر فيقول: \"إنه يعصيني، ولا يطيعني فيما آمر به؛ فلهذا أعاقبه به\" ثم أراد تصديق نفسه في هذا عند لائمه، فأمر عبده بفعلٍ، فإنه يريد أن لا يفعل، ويكون به حكيماً.\rولو أراد أن يفعل ما أمر به في هذه الحالة، فهو سفيه، وإرادة ما لا يرضى به حكمة إذا كانت تحت الإرادة حكمة، وفيما نحن فيه تحتها حكمة، وهي: تحقيق ما علم على ما علم.\rوشبهتهم أن العباد لا يمكنهم الخروج عن إرادة الله تعالى، فتؤدي إلى جعل العباد مجبورين، قلنا: لا يصيرون مجبورين؛ لأنه تعالى أراد منهم الأفعال الاختيارية، فلا يصيرون بها مجبورين، كما أنهم لا يصيرون بعلمه مجبورين وإن كان الخروج عن علم الله تعالى محالاً، وإن الله تعالى علم أنهم يفعلون ما يفعلون باختيارهم، فكذا هذا، والله الموفق، فدل أن ما تعلقوا به من الشبهة فاسد، وما ادعوا ممنوع، والله الموفق."], [121, "فصل في القضاء والقدر وثبوت كون أفعال الخلق مخلوقة لله تعالى\r"]], "pg": [112, 121]}, "466.13": {"x": [[121, "ثبت القضاء والقدر، إذ المراد من قول أهل الحق: \"أن العاصي بقضاء الله تعالى\"، أي: بخلقه؛ إذ القضاء يذكر ويراد به الفعل، قال أبو دويب:\rوعلتهما مسرودتان قضاهما داود أو صنع السوامع تبع\rأي: صنعهما وأحكم صنعتهما. ثم القضاء لفظ مشترك يذكر ويراد به الأمر. قال الله تعالى: {وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ} [الإسراء: 23] أي: أمر ربك. ويذكر ويراد به الإعلام. قال الله تعالى: {وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ فِي الْكِتَابِ} [الإسراء: 4] أي: أعلمناهم. وله معان أخر غير أن مرادنا من ذكر ما ذكرنا الفعل.\rوأما القدر فهو على وجهين:\rأحدهما: الحد الذي يخرج عليه الشيء، وهو جعل كل شيء على ما ينبغي أن يكون عليه، ويقدر كل شيء على ما هو الأولى به.\rوالثاني: ثبات ما يقع عليه كل شيء من زمان أو مكان، وما له من الثواب والعقاب، وكل ذلك ثابت في أفعال الخلق بإثبات الله تعالى"], [122, "على ما مر في مسألة خلق الأفعال، والمعتزلة يقولون: \"إن المعاصي ليست بقضاء الله وقدره\"! وتعلق الكعبي بقول النبي صلى الله عليه وسلم: \"من لم يرضى بقضائي ولم يصبر على بلائي فليطلب ربا سواي\" قال: والكفر غير مرضي!!\rوهذا التعليق منه جهل، فإن عندنا: الكفر مقضى الله تعالى لا قضاؤه، ونحن نرضى بقضاء الله تعالى وجعله الكفر باطلا، ولا نرضى بأن يكون المقضي صفة لنا على أن حقيقة الخبر في الأمراض والمصائب؛ إذ هي التي ربما لا يرضى بها من قضى عليها بها، فأما الكفر ممن قضى به عليه فهو يرضى به أشد الرضا، ويتمسك به أشد التمسك، فلم يكن الخبر وارداً فيه.\rثم المعتزلة لا يرضون بالأمراض والمصائب إلا بعوض، فليطلبوا ربا سوى الله تعالى، ثم الكعبي سمع هذا الخبر الغريب ولم يسمع ما استفاض نقله واشتهر فيما بين النقلة بل في جميع الأمة وهو قوله صلى الله عليه وسلم: <القدر خيره وشره من الله تعالى>، على ما مر في مسألة خلق الأفعال ومسألة الإرادة، والله الموفق."], [123, "فصل في الهدى والإضلال وثبوت خلق الأفعال\r"]], "pg": [121, 123]}, "466.14": {"x": [[123, "يثبت أيضاً مسألة الهدى والإضلال؛ إذ الهدى خلق فعل الاهتداء، والإضلال خلق فعل الإضلال وهو المعنى بقولنا: \"يضل الله من يشاء، ويهدي من يشاء\" دون بيان الطريق فإن ذلك ثابت على العموم، وابتداء الدليل في مسألة قوله: {يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ} [فاطر: 8]، وقوله: {وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ} [البقرة: 272]، وقوله: {وَلَوْ شِئْنَا لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا} [السجدة: 13]، وقوله: {وَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ} [النحل: 9]، وفي آيات كثيرة يطول ذكرها تعدادها وإحصاؤها.\rوللمعتزلة للآيات تأويلات أعرضنا عن ذكرها والجواب عنها مخافة الإطالة، واتكالاً على ما أودع في مسألة خلق الأفعال، والله تعالى الهادي."], [124, "فصل في إبطال القول بالأصلح وثبوت مسألة خلق الأفعال وكون الكفر\rوالمعاصي مخلوقة لله تعالى وإن كان يتضرر بهما الكفار والعصاة\r"]], "pg": [123, 124]}, "466.15": {"x": [[124, "ثبت أن الأصلح ليس بواجب على الله تعالى ولا هو المصلحة، ويظهر بطلان قول المعتزلة: \"أن ما هو الأصح للعبد يجب على الله تعالى أن يفعل بالعبد، ولو لم يفعل ما لا يتضرر به لو فعل وينتفع به العبد، فلو لم يفعل لما انتفع هو به ولتضرر العبد لكان بخيلاً سفيهاً، ثم عندنا على هذا: في مقدور الله تعالى لطف لو فعل بالكفار لآمنوا غير أنه لم يفعل، ولو فعل كان تفضلاً، ولما لم يفعل كان عادلاً لا ظالماً؛ لأنه تعالى ما منع الحق المستحق للغير عليه.\rوعند المعتزلة: ليس في مقدروه ذلك، فلو كان ذلك في مقدوره ولن يفعل كان بخيلاً ظالماً جائزاً.\rولأهل الحق الآيات التي ذكرناها في مسألة الإرادة والهدى والإضلال؛ إذ في بعضها فعل ما ليس بأصلح، وفي بعضها الامتناع عما فيه الأصلح، وجميع ما ذكرنا من الدلائل في مسألة خلق الأفعال ثابتة ههنا؛ إذ هي عين تلك المسألة؛ لأنه لما كان خالقاً للكفر والمعاصي ــ وذلك شر لهم، وليس لهم فيه مصلحة ــ ثبت أن الأصلح ليس بواجب"], [125, "على الله تعالى، ولا هو المصلحة، وأنه قد يفعل ما ليس بأصلح لهم؛ ولأن القول بما قالت المعتزلة إبطال منه الله تعالى على عباده بالهداية؛ إذ فعل ما فعل على طريق قضاء حق واجب عليه ــ ولا منة في هذا، ولا اتصال ــ فيكون الله تعالى بقوله: {وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ} [البقرة: 105]، وما ذكره من مننه على عباده مخطئاً متصلفاً؛ إذ لا إفضال ولا منة في قضاء حق مستحق عليه، وكذا ــ على زعمهم ــ ليس لله تعالى على النبي محمد صلى الله عليه وسلم نعمة ومنة، وليست تلك على أبي جهل ــ لعنه الله ــ إذ فعل بكل منهما ما في مقدوره من الأصلح له، وكذا فيه تسفيه الله تعالى في طلب شكر ما أدى إليهم؛ إذ هو مستحق على قضاء الحق دون الإفضال، وكذا فيه أن إماتة الرسل والأنبياء عليهم السلام كان أصلح لهم وللمؤمنين من إبقائهم، وإبقاء إبليس وجنوده أصلح لهم وللخلق من إماتتهم، وكذا فيه القول بتناهي قدرة الله تعالى حيث لا يقدر على أن يفعل بأحد أصلح مما فعل، ولم يبق في مقدوره ولا في خزائن رحمته أنفع لهم مما أعطاهم، وكل هذا كفر وضلال، وبالله العصمة عن كل ضلالة وبدعة.\rثم يقال لهم: هل رأيتم إنساناً أمضي عمره في الإسلام ثم ارتد عنه بعد ذلك؟ فلابد أن يقولوا: \"لا\"، فنقول: أي الأمرين أصلح له؟ الإماتة قبل أن يرتد بساعة ليختم بالإسلام والسعادة، أم البقاء إلى أن"], [126, "ارتد؟ فإن قالوا: \"الإماتة كان أصاح له\"؛ فقد أقروا بأنه ترك الأصلح وفعل ضده. وإن قالوا: \"كان الإبقاء أصلح له منن الإماتة على الإسلام\"؛ ظهر عنادهم ومكابرتهم، وصارت عقولهم ضحكة للعوام.\rثم يقال لهم: رأيتم صبياً مات في صغره، والآخر عاش حتى بلغ وأسلم وختم له بالإسلام، والآخر بلغ وكفر وارتد بعد الإسلام؟ فلابد من \"نعم\"؛ قيل لهم: أبقى الذي علن أنه أسلم وختم له بالإسلام، فإن قالوا: لأنه أصلح له فأنه ينال بإسلامه وما أتى به من الطاعات الثواب العظيم. قيل: فلم يبق الذي أماته صغيراً؟ فإن قالوا بأن ذلك أصلح له لأن الله تعالى علم أنه لو بلغ لكفر واستحق الخلود في النار، فكانت الإماتة له في حالة الصغر أصلح له. قيل: ولم لم يمت الذي علم أنه يرتد ــ بعد بلوغه ــ عن الإسلام كما أمات هذا الصغير؟ ولا انفصال لهم عن هذا البتة، وما يزعمون من أن منع الأصلح بخلاً لما فعل؛ ولأن منع ما كان منه حكمة ــ وهو حق المانع لا حق غيره قبله ــ لن يكون بخلاً، بل يكون عدلاً، ثم الجود إنما يتحقق بالإفضال لا بقضاء الحق المستحق. وعند المعتزلة: لا إفضال، بل كان ذلك قضاء حق واجب عليه. فلن يتصور عندهم تحقيق"], [127, "الجود، وفيما قلنا إثبات الجود، فهو تعالى يؤلم الأطفال، وذلك مما يضرهم، فكان تركه أصلح لهم؟ فزعموا أن ذلك أصلح لهم؛ لأنه يعطيهم الثواب الدائم على ذلك عوضاً عنه، فصار مصلحة لهم، كحجامة الوالد المشفق ولده. قيل: إن الله تعالى قادر على أن يعطيهم في الدار الآخرة ما يعطيهم بدون سابقة الإيلام، فكذا الإعطاء بذلك أنفع لهم وأصلح، بخلاف الأب؛ لأنه لا بقدر على إثبات الصحة ودفع المرض إلا بالحجامة، حتى إنه لو كان قادراً على الصحة ودفع المرض بدون الحجامة ومع ذلك آلمه بالحجامة لم يعد ذلك منه مصلحة. فإن قالوا: نعم الله تعالى يقدر على ذلك، ولكن إعطاءهم النعمة في الآخرة عوضاً عما لحقه من الألم، كان أصلح له من الإعطاء بدون سابقة الإيلام، لأن ما كان جارياً مجرى الأعواض لا يتمكن فيه المنة المنقصة للنعم، وما كان تفضلاً يتمكن فيه المنة المنقصة للنعم، وكان الثابت بطريق العوض الذ وأشهى، قيل لهم: لحوق المنة إنما ينقص النعمة إذا كان مما يساوي المنعم عليه ويوازيه في الرتبة؛ فيشق على المنعم عليه تحمل منته والخضوع له. فأما المنة من الله تعالى فمما تزيد في النعمة طيباً وتلذذاً للمنعم عليه بامتنانه عليه. يحققه أن ملكاً من الملوك لو خلع على واحد من كبراء أهل مملكته، كان ذلك ألذ عنده وأشهى مما لو اشتراه بعوض يماثله لنا أن لا يشق على الطباع تحمل المنة من الملوك، ولا تكره نفوسهم الخضوع لهم، ففي حق"], [128, "الله تعالى أولى أن يكون الأمر كذلك. والذي يؤيد هذا أن تحمل المنة من الله تعالى لو كان يوجب تنقيص النعم لما من الله تعالى على عباده بالهداية لما فيه من تنقيص النعم، وهد الصنيعة ــ أي الإحسان ــ وكانت نعمة الهداية منقصة على الناس حيث من الله تعالى بقوله: {بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ لِلْإِيمَانِ} [الحجرات: 17].\rوفي الجملة هذا كلام لا يستجيز من عرف الله أن يخطر بباله بما فيه عن التكلم به، غير أن من دأب المعتزلة أنهم لا يبالون عن التمسك بما فيه الانسلاخ عن الدين، وإبطال المعارف، وجحد الحقائق عند رجائهم الوصول به إلى ترويج أباطيلهم ــ عصمنا الله تعالى عن ذلك ــ على أن كثيراً من الأطفال الذين تألموا في صغرهم ماتوا على الكفر، ولا ينالون العوض في الآخرة، وكان الله تعالى عالماً بعواقب أمورهم، فكان بإيلام من علم منه أنه لا ينال العوض في الآخرة ظالماً، على أن ما كان ظلماً، بغير عوض ينعقد ظلماً إلى أن يرضى من له الحق بالعوض، العوض، ورضا من له العوض بكونه عوضاً، وفيه تحقيق الظلم من الله تعالى، وهو كفر، وبالله العصمة والنجاة عن كل ضلالة.\rولأهل الحق الآيات التي ذكرناها في مسألة الإرادة والهدى والإضلال؛ إذ في بعضها فعل ما ليس بأصلح، وفي بعضها الامتناع عما فيه الأصلح، وجميع ما ذكرنا من الدلائل في مسألة خلق الأفعال ثابتة ههنا؛ إذ هي عين تلك المسألة؛ لأنه لما كان خالقاً للكفر والمعاصي،"], [129, "وذلك شر لهم، وليس فيه مصلحة؛ ثبت أن الأصلح ليس بواجب على الله تعالى ولا هو المصلحة، وأنه قد يفعل ما ليس بأصلح لهم؛ ولأن القول بما قالت المعتزلة إبطال منة الله تعالى على عباده بالهداية، إذ فعل ما فعل على طريق قضاء حق واجب عليه، ولا منة في هذا ولا إفضال؛ فيكون الله تعالى بقوله {وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ} [البقرة: 105] وما ذكر من مننه على عباده مخطئاً متصلفاً، إذ لا إفضال ولا منة في قضاء حق مستحق عليه، وكذا على زعمهم ليس لله تعالى على النبي صلى الله عليه وسلم نعمة ومنة ليست علي أبي جهل ــ لعنه الله ــ إذ فعل بكل منهما ما في مقدوره من الأصلح له، وكذا في تسفيه الله تعالى في طلب شكر ما أدى إليهم؛ إذ هو مستحق على الإفضال دون قضاء الحق، وكذا فيه أن إماتة الرسل والأنبياء عليهم السلام كان أصلح لهم وللمؤمنين من إبقائهم، وإبقاء إبليس وجنوده أصاح لهم وللخلق من إماتتهم، وكذا فيه القول بتناهي قدرة الله تعالى حيث لا يقدر على أن يفعل بأحد أصلح مما فعل، ولم يبق في مقدوره ولا في خزائن رحمته أنفع لهم مما أعطاهم، وكل هذا كفر وضلال، وبالله العصمة عن كل ضلال وبدعة.\rثم يقال لهم: هل رأيتم إنساناً أمضى عمره في الإسلام ثم ارتد عنه بعد ذلك؟ فلا بد من أن يقولوا: نعم فنقول: أي الأمرين أصلح له،"], [130, "الإماتة قبل أن يرتد بساعة ليختم بالإسلام والسعادة أم البقاء إلى أن ارتد؟ فإن قالوا: الإماتة كان أصلح له من الإماتة على الإسلام، ظهر عنادهم ومكابرتهم، وصارت عقولهم ضحكة للعوام.\rثم يقال لهم: رأيتم صبياً مات في صغره، والآخر عاش حتى بلغ أسلم وختم له بالإسلام، والآخر بلغ وكفر وارتد بعد الإسلام؟ فلابد من \"نعم\". قيل لهم: أبقى الذي علم أنه أسلم ويختم له بالإسلام، فإن قالوا: لأنه أصلح له، فإنه ينال بإسلامه وما أتى من الطاعات الثواب العظيم. قيل: فلم لم يبق الذي أماته صغيراً؟ فإن قالوا: بأن ذلك أصلح له؛ لأن الله تعالى علم أنه لو بلغ لكفر واستحق الخلود في النار، فكانت الإماتة له في حالة الصغر أصلح له، قيل: ولم لم يمت الذي علم أنه يرتد بعد بلوغه عن الإسلام كما أمات هذا الصغير؟ ولا انفصال لهم عن هذا ألبتة، وما يزعمون أنه منع الأصلح بخل فاسد؛ لأنا بينا بالدليل أن الله تعالى فعل ذلك، ولو كان بخلاً لما فعل، ولأن منع ما كان منه حكمة وهو حق المانع لا حق غيره قبله، لن يكون بخلاً بل يكون عدلاً. ثم الجود إنما يتحقق بالإفضال لا بقضاء الحق المستحق، وعند المعتزلة لا إفضال بل كان ذلك قضاء حق واجبٍ عليه، فلن يتصور عندهم تحقيق"], [131, "الجود، وفيما قلنا إثبات الجود، فهو تعالى بما يعطى متفضل جوداً، وبما يمنع مما هو حقه لا حق غيره قبله عادل، والله الموفق."], [132, "فصل في إثبات عذاب القبر للكافرين ولبعض العصاة من المؤمنين، والإنعام لأهل الطاعة في القبر\r"]], "pg": [124, 132]}, "466.16": {"x": [[132, "وسؤال منكر ونكير ثابت لورود الدلائل السمعية في ذلك من قوله تعالى: {النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا} [غافر: 46] وليس ذلك إلا عذاب القبر، وقال تعالى في قوم نوح عليه السلام: {أُغْرِقُوا فَأُدْخِلُوا نَارًا} [نوح: 25]، والفاء للترتيب والتعقيب بلا تراخ، فيكون ذلك في الدنيا. والمروي عنه صلى الله عليه وسلم: أنه مر بقبرين جديدين، فقال: <إنهما ليعذبان، وما يعذبان بكبير، أما أحدهما: فإنه كان لا يستنزه من البول، والآخر: كان يمشي بالنميمة> والخبر المعروف في الملكين اللذين يسألان الميت ومعهما مرزبتان، وقول عمرـ رضي الله عنه ــ على أثر ذلك: أو يكون معي عقلي؟ قال: \"بلى\" قال: يا رسول الله فإذا أكفاهما.\rوالدعاء المتوارث في الأمة من غير نكير، وقوله: \"وقنا عذاب القبر\"، و\"عذاب النار\"، ولا معنى لإنكار جهم، وبعض المعتزلة"], [133, "أنكر ذلك، وتعليلهم أن تعذيب من لا حياة له والسؤال له والجواب منه مستحيل وهو غير مستحيل لما أن ذلك لما ثبت بالدلائل التي لا وجه إلى ردها، ومن الممكن أن يعيد الله تعالى نوع حياة مقدار ما يتألم به ويتلذذ ويعلم أن الواجب تلقى الدلائل بالقبول، ويثبت ذلك على وجه الممكن. ثم لم يثبت دليل على أنه تعالى نوع حياة مقدار ما يتألم به ويتلذذ ويعلم أن الواجب تلقى الدلائل بالقبول، ويثبت ذلك على وجه الممكن. ثم لم يثبت دليل على أنه تعالى يقيم به نوع حياة بلا إعادة الروح، أو يعيد إليه الروح، فيتوقف في ذلك، فأما إثبات حياة ما فلا توقف فيه لمشايخنا، فإن تعذيب من لا حياة له غير مستقيم عندنا، فإن الحياة عندنا شرط لثبوت العلم، خلافاً للكرامية والصالحية، وهم أتباع الحسن الصالحي، فيكون القول بإثبات عذاب القبر بدون الحياة على قوول هؤلاء والله الموفق."], [134, "فصل في وعيد فساق المسلمين\r"]], "pg": [132, 134]}, "466.17": {"x": [[134, "اختلف الناس في العصاة من أهل القبلة في أسمائهم وأحكامهم، فزعم جمهور الخوارج أن كل من عصى صغيرة كانت المعصية أو كبيرة، فاسمه الكافر لا المؤمن، وحكمه أنه يخلد في النار في الآخرة. أما الحكم فلقوله تعالى: {وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا} [النساء: 14]، والذنوب كلها في تحقيق اسم العصيان واحد، فأما الاسم فلقوله تعالى: {وَاتَّقُوا النَّارَ الَّتِي أُعِدَّتْ لِلْكَافِرِينَ} [آل عمران: 131]، لما كان النار معدة للكافرين، فكل من أوعد بها فهو كافر، وقوله: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ} [المائدة: 44]، لا المؤمن ولا الكافر، فيخرج بها صاحبها عن الإيمان ولا يدخل في الكفر، فيكون له منزلة بين منزلتين، لما أن الناس اختلفوا فيه، منهم من قال: إنه مؤمن بما معه من التصديق، وفاسق بما اقترف من الذنب، وهو قول الجماعة، ومنهم من قال: إنه كافر وهو فاسق، وهو قول الخوارج، ومنهم من قال: إنه منافق وهو فاسق، وهو قول الحسن"], [135, "البصري ومن تابعه، فاتفقت الأمة على إطلاق اسم الفاسق، واختلفوا فيما وراء ذلك، فأخذنا بالمتفق وتركنا ما اختلفوا فيه، فقلنا إنه فاسق وليس بمؤمن ولا كافر ولا منافق، وحكمه أنه يخلد في النار إن مات قبل التوبة لقوله تعالى: {وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا} [النساء: 93]، وقوله: {إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا} [النساء: 10]، وقوله تعالى: {إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا} [النساء: 10] جعل الفاسق بمقابلة المؤمن، وجعل الفاسق قسماً والمؤمن بمقابلته قسماً، فدل أن الفاسق غير والمؤمن غير، ثم بين حكم كل واحد منهما فقال: {أَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ"], [136, "جَنَّاتُ الْمَأْوَى نُزُلًا بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 19] فكان في هذه الآية دليل الاسم والحكم جميعاً. قالوا: وإن كانت المعصية صغيرة فاسم مقترفها المؤمن، وحكمه أنه إذا اجتنب الكبائر لا يجوز تعذيبه على الصغائر لقوله: {إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ} [النساء: 31].\rوأما أهل الحق فإنهم يقولون: إن من اقترف كبيرة غير مستحيل لها ولا مستخف بمن نهى عنها بل لغلبة شهوة أو حمية نرجو الله تعالى أن يغفر له، ونخاف أن يعذبه عليه، فهذا اسمه المؤمن، وبقي على ما كان عليه من الإيمان، ولم يزل عند إيمانه ولم ينتقص، ولا يخرج من الإيمان إلا من الباب الذي دخله، وحكمه أنه لو مات من غير توبة فلله تعالى فيه المشيئة إن شاء عفا عنه بفضله وكرمه، أو ببركة ما معه من الإيمان والحسنات، أو بشفاعة بعض الأخيار، وإن شاء عذبه بقدر ذنبه ثم عاقبة أمره الجنة لا محالة، ولا يخلد في النار، أما الاسم فلإن الإيمان هو التصديق، والكفر هو التكذيب وهو الذي ارتكب هذه الكبيرة لكسل أو"], [137, "حمية أو أنفة أو غلبة شهوة كان التصديق معه باقياً، وما دام التصديق موجوداً كان التكذيب منعدما لمضادة بينهما، فالقول بكفره والتكذيب منعدم، فالقول بزوال الإيمان والتصديق قائم، أو بثبوت النفاق والتصديق في القلب متقرر قول ظاهر الفساد. ودليل كون الإيمان هو تصديق محمد - صلى الله عليه وسلم - بجميع ما جاء به من عند الله نبيئه إذا انتهينا إلى مسائل الإيمان.\rثم إطلاق اسم الفاسق لما أنه خرج عن حد الائتمار، والفسق في اللغة هو: الخروج، ثم الخروج عن الائتمار على ما بينا من الوجه لايضاد التصديق؛ فيبقى التصديق، وإذا بقي كان المصدق مؤمناً ضرورة.\rوما زعم المعتزلة أنا نأخذ بالمتفق عليه ونترك المختلف فيه قول باطل؛ لأن ذلك يصير إحداث قول لم يكن في الأمة وخروجاً عن جميع أقوال السلف، وهذا خرق للإجماع وخروج عنه، وهو باطل بالإجماع، وفيه أيضاً إحداث القول بمنزلة بين الإيمان والكفر، وهو خروج عن الإجماع، ومخالفة الإجماع من وجهين جهل فاحش. ثم"], [138, "الأمة إذا اختلفت في شيء على أقاويل صار ذلك إجماعاً على أن ما عداها باطل، فكان بعد ذلك البحث عن الأقاويل، وعرضها على الدلائل، واتباع ما شهد الدلائل، واتباع ما شهد الدلائل لصحته. وعند العجز عن التمييز بين الحق والباطل يجب التوقف والرجوع إلى من أكرمه الله بالعلم والخضوع له والتعلم منه، فأما جعل التوقف الذي هو مقتضى تعارض الأدلة ونتيجة العجز عن ترجيح البعض على البعض وموجبات الحيرة مذهباً يتمسك به وعقيدة يدان بها فحيد عما توجبه العقول وتقتضيه الأصول، وبالله العصمة، والذي يؤيد ما قلنا: أن الله تعالى أبقى اسم الإيمان مع وجود ما عليه من الوعيد بقوله تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى} [النساء: 43]، وقوله تعالى:\r{وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا} [الحجرات: 9]، وقوله تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى} [البقرة: 178] الآية."], [139, "وفي الآية دلالة من أوجه ثلاثة:\rأحدها: أنه أبقى اسم الإيمان مع وجوب القصاص الذي هو حكم العمد الخالي عن الشبهة كلها.\rوالثاني: أنه أبقى اسم الأخوة الثابتة بالإيمان بقوله تعالى: {إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ} [الحجرات: 10] بين القاتل وأولياء المقتول بقوله تعالى: {فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ} [البقرة: 178] الآية.\rوالثالث: أنه ما أخرج مرتكب هذه الكبيرة عن اشتمال التخفيف والرحمة بقوله تعالى: {ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ} [البقرة: 178]، والاستدلال بالأوجه الثلاثة روى عن عبد الله بن عباس ــ رضي الله عنهما.\rوقوله: {وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا} [الأنفال: 72] أبقى لغير المهاجر اسم الإيمان مع تعظيم الوعيد يترك الهجرة، وقوله: {يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ} [الممتحنة: 1]، وقوله: {يَاأَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا} [التحريم: 8]، والأمر بالتوبة لمن لا ذنب له محال، وفي الآيات كثرة.\rوإذا ثبت بما ذكرنا من الدلائل السمعية والعقلية بقاء الإيمان واسم المؤمن نقول: له حكمان:\rأحدهما: أن عاقبة أمره الجنة ولا يخلد في النار. دليله قوله تعالى: {إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا (107)"], [140, "خَالِدِينَ فِيهَا} [الكهف: 107]، وهذا مؤمن وقد عمل الصالحات، وقوله تعالى: {إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ذَلِكَ الْفَوْزُ الْكَبِيرُ (11)} [البروج: 11]، وقوله تعالى: {إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ (7)} [البينة: 7]، وقوله: {إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَأُولَئِكَ لَهُمْ جَزَاءُ الضِّعْفِ بِمَا عَمِلُوا} [سبأ: 37]، وقوله: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ} [الزلزلة: 7]، وقوله: {مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا وَمَنْ جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى إِلَّا مِثْلَهَا} [الأنعام: 160]، في آيات كثيرة لا تحصى.\rثم عن هذا الرجل أتى بما هو أفضل الطاعات ونهاية الخيرات، والشر الذي أتى به لا يبلغ نهاية الجحود، فلو خلد في النار وأبطل ثواب أفضل الخيرات ونهايتها، وما أتى من الطاعات، بارتكاب ما ليس بنهاية من الشرور ولا له كثرة بل ارتكب مرة أو مراراً محصورةً، مع ما اقترن به مما هو عبادة عظيمة من خوف العقوبة ورجاء عفو خالقه؛ فقد زيد في عقاب شر واحد، ونقص من ثواب الخيرات. وفيه خلف ما وعد من أن يجزى الحسنة بعشر أمثالها، والسيئة بمثلها، بل وعد سبعمائة بقوله تعالى: {مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ} [البقرة: 261] الآية.\rبل وعد أضعافاً مضاعفة بقوله: {مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ} [البقرة: 245] الآية."], [141, "فإذا على زعمهم أيضاً ما اقتصر في السيئات على جزاء مثلها، بل زاد عليها ما لا نهاية له، ولم يجز على حسنة مثلها فضلاً عن العشرة والسبعمائة، وهذا هو الخلف الذي وراء خلف.\rثم إنهم ينسبون أهل الحق في تجويزهم العفو عن الكبيرة إلى الخلف في الوعيد، وهذا تحكم في الوعيد ظاهر، والله الموفق.\rوالحكم الآخر جواز المغفرة وتعليق التعذيب بالمشيئة، وذلك ثابت بقوله تعالى: {إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} [النساء: 48]، وهذا نص ومعناه ظاهر، ولأنه تعالى عفو غفور وإنما تحقق العفو والمغفرة عما هو جائز التعذيب، فأما ما لا جواز للتعذيب عليه، فترك التعذيب لا يكون عفواً ولا مغفرة، كترك التعذيب على المباحات، وعلى زعم المعتزلة والخوارج لا تحقق للعفو والمغفرة ألبتة، ولا يقال: يعفو عن الصغائر؛ لأن عندهم لو كان يرتكب الصغيرة اجتنب الكبائر، فهو غير جائز التعذيب، فلا يكون ترك التعذيب عليه مغفرة وعفواً، وإن كان قد ارتكب الكبائر والصغائر فالصغائر غير جائز العفو عند أكثرهم؛ لأنه لو جاز له العفو لما جاز التعذيب، ومن جوز منهم العفو عن الصغائر في تلك الحالة، وجوز التعذيب أيضاً؛ فهو مناقض أصوله في الإيجاب، فعلى ما هو الأصلح عندهم ولما وصف الله تعالى نفسه دل أن العفو عن صاحب الكبيرة جائز، يحققه: أن الله تعالى"], [142, "أمر النبي صلى الله عليه وسلم باستغفار للمؤمنين، وكذلك الأنبياء والرسل والملائكة عليهم السلام يستغفرون للمؤمنين، فلو كلن ذلك استغفاراً عما لا يجوز عليه التعذيب لكان هذا سؤالاً أن لا يظلم الله تعالى عباده، ومن ظن أن الله تعالى امر بذلك أنبياءه ورسله وملائكته، أو أنهم اشتغلوا بذلك؛ فقد كفر من ساعته. وإن كان استغفاراً عما يجوز التعذيب عليه صح ما ذهبنا إليه، وبطل مذهب الخصم، والله الموفق.\rثم ما في الآيات من إثبات الخلود في النار فكذلك محمول على المستحلين بدليل ما ذكرنا من الدلائل السمعية والعقلية، ثم قوله تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ} [البقرة: 178] الآية، وقوله: {أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا لَا يَسْتَوُونَ} [السجدة: 18] الآية، فيه مقابلة الفاسق المطلق بالمؤمن، والفاسق المطلق هو الكافر، فأما من معه من الطاعات ما يحصى كثرة والتصديق فيه قائم فهو ليس بفاسق مطلق، والكلام فيه لا في ذاك، ألا ترى أنه قال في سياق الآية: {وَقِيلَ لَهُمْ ذُوقُوا عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ (20)} [السجدة: 20]؟. ومن كذب بالنار فهو كافر لا صاحب كبيرة، وكذا صاحب الكبيرة لا يوصف بأنه متعد حدود الله تعالى، بل"], [143, "ذلك الكافر الذي تعدى جميع حدود الله تعالى. فأما صاحب الكبيرة فقد راعى حدود الله تعالى في أشياء كثيرة، والله الموفق.\rثم صاحب الصغيرة عندنا جائز التعذيب أيضاً؛ لدخوله تحت قوله تعالى: {وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} [النساء: 48]، وقوله: {إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ} [النساء: 31]، جاء في التفسير أنه من أنواع الكفر، يدل عليه أنه قرئ: كبير ما تنهون عنه\"، وهو الكفر، وبالله العصمة والتوفيق."], [144, "فصل في إثبات الشفاعة\r"]], "pg": [134, 144]}, "466.18": {"x": [[144, "وإذ ثبت جواز المغفرة لصاحب الكبيرة جاز أن يغفر بشفاعة الأنبياء والرسل عليهم السلام، وبشفاعة الأخيار، وعند المعتزلة: لما كانت مغفرته ممتنعة بدون الشفاعة لن يتصور مغفرتها بالشفاعة، ثم ابتداء الدليل لنا في المسألة قوله تعالى: {فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ} [المدثر: 48]، ولو كان لا شفاعة لغير الكافر أيضاً لم يكن لتخصيص الكافر بالذكر في حال تقبيح أمرهم معنى.\rوروى ــ على طريق الاستفاضة ــ أنه عليه السلام قال: \"شفاعتي لأهل الكبائر من أمتي\"، وهذا الحديث يبطل حديث المعتزلة الذي ما وردت الشفاعة فيه أنها للمطيعين، وهي أن يطلب الرسل والملائكة من الله تعالى أن يزيدهم على ما استحقوا من الثواب من فضله بقوله: {لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ} [فاطر: 30]، فإنه عليه السلام نص على أن شفاعته لأهل الكبائر، ولأن ما ذكروا يسمى إعانة لا شفاعة، بل هي في المتعارف اسم لطلب التجاوز؛ فصرفها عن"], [145, "المفهوم إلى ما يفهم دخوله تحت الاسم تحريف للكلم عن مواضعها، ولأن تلك الزيادة عندهم إذ لم تكن مستحقة بالعمل توجب تنغيص نعمة الجنة؛ إذ من زعمهم أن التفضيل يوجب المنة، وهي تخصيص وليست الجنة بدار تنغص فيها النعم.\rولأن إعطاء تلك الزيادة لو كان عندهم جائزاً بدون الشفاعة لكان لا يجوز منعها؛ لأن منع ما يجوز إعطاؤه من غير أن يكون للمانع فيه منفعة أو دفع مضرة وينتفع به المعطى بخل عندهم، وطلب ما لا يجوز نفعه طلب الامتناع عن الظلم والجور والسفه، ومن ظن أن الأنبياء والمرسلين عليهم السلام والملائكة المقربين يسألون من الله تعالى ما هذا سبيله فهو كافر، والله الموفق.\rولا تعلق لهم بقوله تعالى: {وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى} [الأنبياء: 28]؛ لأن المؤمن بما معه من الإيمان والطاعات مرتضى وإن وجدت منه كبيرة، وقيل: معناه لا يشفعون إلا لمن ارتضى الله تعالى الشفاعة له، فلم زعمتم أن الله تعالى لا يرضى شفاعة صاحب الكبيرة؟ ولا تعلق لهم أيضاً بقوله تعالى: {مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ} [غافر: 18] لأن الظالم المطلق هو الكافر على ما مر، والله الموفق."], [146, "فصل في ماهية الإيمان\r"]], "pg": [144, 146]}, "466.19": {"x": [[146, "الإيمان في اللغة: عبارة عن التصديق، فكل من صدق غيره فيما يخبره يسمى في اللغة مؤمناً، ومؤمناً له. قال الله تعالى ــ خبراً عن إخوة يوسف صلوات الله عليهم: {وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا} [يوسف: 17]؛ أي: بمصدق لنا، ثم إن هذا المعنى اللغوي وهو التصديق بالقلب هو حقيقة الإيمان الواجب على العبد حقا لله تعالى، فمن أتى بهذا التصديق فهو مؤمن فيما بينه وبين الله تعالى، والإقرار يحتاج إليه ليقف عليه الحسن الأشعري، وهو أيضاً قول الحسن بن الفضل البجلي من متكلمي أهل الحديث، ووجهه أنه لما كان عبارة عن التصديق، فمن جعله لغير التصديق فقد صرف الاسم عن المفهوم في اللغة إلى غير المفهوم، وفي تجويز ذلك إبطال اللسان وتعطيل اللغة إلى غير المفهوم، وفي تجويز ذلك إبطال اللسان وتعطيل اللغة، ورفع طريق الوصول إلى اللوازم الشرعية والدلائل السمعية، يحققه: أن ضد الإيمان هو الكفر، والكفر هو التكذيب والجحود،"], [147, "وهما يكونان بالقلب، فكذا ما يضادهما؛ إذ لا تضاد يتحقق عند تغاير المحلين، والذي يدل عليه ما فرق بين العبادات بالأسماء المعطوفة المفعولة لها على ما قال تعالى: {إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ} [التوبة: 18]، فقد عطف إقامة الصلاة وإيتاء الزكاة على الإيمان، ولا شك في ثبوت المغايرة بين المعطوف والمعطوف عليه، وقال تعالى: {إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ} [يونس: 9]؛ ولهذا يفزع أعداء الله عند معاينة العذاب إلى التصديق دون غيره من الأفعال، كما فعل فرعون وقوم يونس عليه السلام، يحققه أن الله تعالى خاطب بالاسم الإيمان، ثم أوجب الأعمال على ما قال تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ} [البقرة: 183]، وذا دليل التغاير، وقصر أسم الإيمان على التصديق، وبالوقوف على هذا ثبت بطلان قول من جعل الأعمال إيماناً وهو قول فقهاء أصحاب الحديث وأكثر متكلميهم، يحققه أنهم لو جعلوا اسم الإيمان واقعاً على مجموع التصديق والإقرار والأعمال كلها لأوجب ذلك زوال الإيمان بزوال بعض الأعمال، أو بزوال كلها، وأهل الحديث يأبون هذا،"], [148, "يؤيد هذا أن من آمن وصدق ومات من ساعته قبل توجه أداء شريعة من الشرائع وعبادة من العبادات عليه، وقلب اشتغاله بأدائها، مات مؤمناً، ولو كان الأمر كما زعموا ينبغي أن يصير مؤمناً ما لم يأت بالأعمال، وذا باطل بالإجماع، ولو كان كل عمل إيماناً على حدة لكان الإيمان والأديان كثيراً، ويكون المنتقل من عبادة إلى عبادة متنقلا من إيمان إلى إيمان، ومن دين إلى دين، فالقول به باطل، وينبغي أن يقال: إن الجنب منهي عن تحصيل الإيمان، والمفسد للصوم والصلاة مبطل للإيمان، وذا كل باطل، يحققه أن كل عبادة من الصلاة والزكاة والحج والصوم لها اسم خاص تعرف به خاصيتها، لا يشاركها في ه غيره، فما بال أرفع العبادات وهو التصديق ليس له اسم خاص يمتاز به عن غيره، يؤيده أنه تعالى جعل الإيمان شرطاً لقيام الأعمال الصالحة بقوله تعالى: {فَمَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِ} [الأنبياء: 94]، ولو كان الإيمان اسما لكل عبادة لكان شرط أبو منصور ــ رحمه الله ــ في تصنيف مفرد له في هذه المسألة، ولا تعلق للخصوم بقوله تعالى: {وَمَا كَانَ اللَّهُ"], [149, "لِيُضِيعَ إِيمَانَكُمْ} [البقرة: 143]؛ أي: صلواتكم إلى البيت المقدس؛ لأنه يحتمل أن المراد من الآية تصديقهم بكون الصلاة جائزة عند التوجه إلى بيت المقدس؛ إذ الواجب فيها هو التوجه إليه، ويحتمل أن المراد نفس الصلاة غير أنها سميت به مجازاً لما أنه لا صحة لها بدون الإيمان، أو لأنها دلالة على الإيمان، ولا كلام في ذلك، إنما الكلام في الحقيقة، والله الموفق.\rوإذ ثبت أن الإيمان هو التصديق وهو لا يتزايد في نفسه دل أن الإيمان لا يزيد ولا ينقص، فلا زيادة له بانضمام الطاعات إليه، ولا نقصان بارتكاب المعاصي، إذ التصديق في الحالين على ما كان قبلهما فكان ورد به من الزيادة في الإيمان ما روى عن أبي حنيفة ــ رحمه الله ــ أنهم كانوا آمنوا في الجملة ثم يأتي فرض فيؤمنون بكل فرض خاص؛ فزاد إيمانهم بالتفصيل مع إيمانهم بالجملة، وكذا هذا التأويل مروي عن ابن عباس ــ رضي الله عنهما ــ وكذا الثبات على الإيمان والدوام عليه زيادة عليه في كل ساعة، والله تعالى الموفق."], [150, "وبالوقوف على أن الإيمان هو التصديق يعرف بطلان قول من جعل الإيمان مجرد القول كما ذهب إليه الرقاشي عبد الله بن سعيد القطان والكرامية، ويقول: ليس في القلب منه شيء لأنا بينا أنه التصديق، والإقرار باللسان دليل عليه لا أن يكون مجرد الإقرار إيماناً، يحققه أن الله تعالى قال في المنافقين: {الَّذِينَ قَالُوا آمَنَّا بِأَفْوَاهِهِمْ وَلَمْ تُؤْمِنْ قُلُوبُهُمْ} [المائدة: 41]، ولو لم يكن في القلب إيمان لم يكن لهذا القول فائدة، ولصار هذا أيضاً وصف الرسل والصحابة وجميع المؤمنين، وكانوا معيرين بما عير به المنافقون، أو كان الله تعالى عير المنافقين بما عليه الرسل عليهم السلام والصحابة، وكان مخطئاً في تعييرهم بذلك، وكلا القولين كفر، وقال الله تعالى: {قَالَتِ الْأَعْرَابُ آمَنَّا} [الحجرات: 14] إلى أن قال: {وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ} [الحجرات: 14]، ولو كان الإيمان باللسان دون القلب لكان قولهم: (آمنا) إيماناً، ولصار الأمر بأن يقول لهم: (لم"], [151, "تؤمنوا) أمر بأن يكذب، ومن زعم أن الله تعالى أمر رسوله عليه السلام بأن يكذب، فقد كفر، وكذا لم يكن لقوله: {وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ} معنى؛ لأنهم يقولون للنبي والصحابة: (ولما يدخل الإيمان في قلوبكم) أيضاً، وفساد هذا ظاهر لا يخفى، وهذا واضح لا معنى للإطناب فيه، وإيراد جميع ما هو الدليل في الباب، ثم إن عند عبد الله بين سعيد إذا وجد التصديق بالقلب والإقرار باللسان كان الإقرار هو الإيمان لا التصديق، وإذا انعدم التصديق لم يكن مجرد القول إيماناً، فكان التصديق بالقلب والإقرار باللسان كان الإقرار هو الإيمان لا التصديق، وإذا انعدم التصديق لم يكن مجرد القول إيماناً، فكان التصديق بالقلب والإقرار باللسان كان الإقرار هو الإيمان لا التصديق، وإذا انعدم التصديق لم يكن مجرد القول إيماناً، فكان التصديق لكون الإقرار إيماناً، فعلى قوله لم يكن أهل النفاق مؤمنين بمجرد إقرارهم لما انعدم التصديق، فأما الكرامية فإنهم يزعمون أن الإقرار المجرد هو الإيمان بدون شرطية التصديق، والمنافق عندهم مؤمن حقاً وليس بكافر مع أن الله تعالى سماه كافراً بقوله: {سَوَاءٌ عَلَيْهِمْ} [البقرة: 6] إلى قوله: {ذَلِكَ بِأَنَّهُمْ كَفَرُوا بِاللَّهِ}، وهذا رد للنص وتخطئة لله في تسميته كافراً، وكل ذلك كفر، وفيه جعل من خرج في الدنيا مؤمناً حقاً مستحقاً للخلود في الدرك الأسفل من النار، وهؤلاء الجهال الضلال يجعلون من أكره على إجراء كلمة الكفر على لسانه كافراً حقاً مع أن قلبه مطمئن بالإيمان، ثم يجعلونه من أهل الجنة خالداً مخلداً، وفساد هذا كله لا يخفى، ثم إن الله تعالى بين في هذه الآية أن الإيمان في القلب بقوله: {إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ} [النحل: 106]، فيكون راده كافراً، والله الموفق، يحققه أن من اشتغل"], [152, "بقضاء حاجته في الكنيف منهي عن إجراء كلمة الإخلاص على اللسان، وكذا يكره ذلك في بعض الأحوال، كما في حالة اشتغاله بالقراءة في الصلاة، يكره قطع نظم القرآن والاشتغال بإجراء كلمة الإخلاص على لسانه، والقول بالنهي عن الإيمان وكراهيته باطل جداً، وهذا قول يغني حكايته عن الأطناب، وبالله العصمة، وكذا بالوقوف على أن الإيمان هو التصديق يعرف فساد قول جهم: إن الإيمان هو المعرفة، يحققه أن أهل العناد كانوا يعرفون النبي صلى الله عليه وسلم كما كانوا يعرفون أبناءهم ــ بشهادة الله تعالى ــ وكانوا يكتمون الحق وهم يعملون، وما كانوا مؤمنين حيث لم يصدقوا، والمؤمنون آمنوا بالكتب والرسل والملائكة، ولا معرفة يعرف بطلان قول جهم ومن ساعده، وبالله التوفيق.\rوإذا عرفت أن الإيمان هو التصديق وهو أمر حقيقي لا يتبين بانعدامه وتبدله بما يضاده أنه ما كان موجوداً؛ كمن كان قائماً ثم قعد، أو كان شاباً ثم شاخ، لم يتبين أنه ما كان قائماً ولا شاباً، وعرف بهذا بطلان قول الأشعرية ومن ساعدهم في \"الموافاة\"، وهو القول: أن العبرة للختم، فمن ختم له بالإيمان تبين أنه كان من الابتداء مؤمنا، وحين كان خر ساجداً بين يدي الصنم معتقداً للشرك والأديان الباطلة كان مؤمناً مصدقاً لله تعالى ورسوله مؤمناً مخلصاً آتياً بالعبادات كان كافراً من الابتداء،"], [153, "وهذا ظاهر الفساد وقضية هذا أن من شاخ يتبين أنه كان شيخاً كان مترعرعاً وفي حال عنفوان شبابه، بل حين كان طفلاً رضيعاً في المهد، بل حين كان في بطن الأم، والقول به إنكار للحقائق، وبالله"], [154, "وبهذا يعرف أيضاً بطلان قولهم: \"إنا مؤمنون إن شاء الله؛ لأن ذلك كشاب يقول: \"أنا شاب إن شاء الله تعالى\"، وكطويل يقول: \"أنا طويل إن شاء الله تعالى\"، وذلك كله هذيان، فكذا هذا، والله الموفق."], [155, "فصل في الأمامة\r"]], "pg": [146, 155]}, "466.20": {"x": [[155, "قال المسلمون: لا بد لهم من إمام يقوم بتنفيذ أحكامهم، وإقامة حدودهم، وسد ثغورهم المتلصصة، وتجهيز جيوشهم، وأخذ صدقاتهم، وقطع مادة شرور المتغلبة والمتسلطة، وقطاع الطريق، وإقامة الجمع والأعياد، وقطع المنازعات الواقعة التي لو دامت لأفضت إلى التقاتل والتفاني، وقبول الشهادات القائمة على الحقوق، وتزويج الصغار والصغائر الذين لا أولياء لهم، وقسمة ما أفاء الله تعالى عليهم من الغنائم؛ ولهذا اجتمعت الصحابة ــ رضي الله عنهم ــ على نصب الإمام، وعرف بطلان قول أبي بكر الأصم وهشام بن عمرو من رؤساء القدرية ــ لعنهم الله ــ \"إن نصب الإمام ليس بواجب\"، وتعليل الأصم أن الناس لو كفواً عن المظالم لاستغنوا عن الإمام تعليل فاسد لما مر من إثبات الحاجة إلى أمور كثيرة وراء قطع المنازعات، والإنصاف والانتصاف، على أن قوماً لو استغنوا عنه لكانت الصحابة ــ رضي الله عنهم ــ مع جلال"], [156, "أقدارهم وشدة احتراسهم عما لا يحل ولا يحمد، وامتناعهم عن الظلم والتعدي، أولى الناس بالاستغناء، وحيث لم يستغنوا عنه دل أن ذلك ليس بشيء، والله الموفق.\rثم ينبغي أن يكون الإمام في كل وقت ظاهراً يمكنه القيام بما نصب هو له؛ إذ نصب من لا يمكنه القيام بذلك غير مفيد، وبهذا يبطل قول الروافض، بإمام غائب مختف ينتظرون خروجه، والله الموفق.\rثم المروى الذي انقادت له الصحابة، وسلمت الأنصار الأمر للمهاجرين، وأجمعوا جميعاً على إمامة الصديق ــ رضي الله عنه ــ وهو قوله عليه الصلاة والسلام: <الأئمة من قريش>؛ يقتضي أن يكون كونه قرشياً شرطاً، ولا يختص بطن من قريش دون بطن. وانعقد الإجماع على هذا حيث سلمت الأنصار ــ رضي الله عنهم ــ الأمر عند سماعهم هذا الخبر، وثبت أن كونه هاشمياً ليس بشرط، وانعقاد الإجماع على الصديق ــ رضي الله عنه ــ دليل على وجوب إجراء الحديث على العموم في جميع بطون قريش، ولا اختصاص لبطن منهم، وبه بطل قول الروافض في الاقتصار على بني هاشم أو على علي وأولاده ــ رضي الله عنهم ــ وبه بطل أيضاً قول الضرارية: \"إن الإمامة تصلح في غير قريش\"، وقول الكعبي، حيث زعم أن القرشي أولى بها، فإن خافوا الفتنة جاز عقدها لغير القرشي."], [157, "ثم إن المتكلمين بنوا الأمر في هذه المسألة على مجرد الشرع الوارد في تعين القرشي دون الكشف عن المعنى، والشيخ أبو منصور الماتريدي ــ رحمه الله ــ ذكر في ذلك معاني معقولة مثبتة، وحكمة بليغة لا وجه لذكرها في مثل هذا الكتاب، وقد ذكرت ذلك كله في كتاب \"تبصرة الأدلة\"، ثم للمتكلمين كلام كثير فيما يشترط من الصفات الثابتة للإمامة، وبينهم خلاف، ولهم أقاويل مختلفة لا وجه لذكرها في هذا الكتاب، وقد ذكرت ذلك كله في كتاب \"تبصرة الأدلة\" ــ بحمد الله ومنه ــ ثم إن أبا بكر الصديق ــ رضي الله عنه ــ استجمع فيه مع كونه قرشياً جميع ما يحتاج إليه في الأمامة، وينصب هو لأجله من العلم والديانة والورع، والصلابة في الدين، ورباطة الجأش، والعلم بتدابير الحروب، والقيام بتهيئة الجيوش، وتنفيذ السرايا، ومعرفة سياسة العامة، وتسوية أمور الرعية، وغير ذلك مما يحتاج إليه في الأمامة؛ ولهذا اختارته الصحابة ــ رضوان الله عليهم أجمعين ــ على إمامته، إما استدلالاً منهم بتفويض النبي صلى الله عليه وسلم إقامة ما هو من أعظم أركان الدين ــ وهو الصلاة ــ إليه، وأمره بأن يحج بالناس سنة تسع عند قعود عليه الصلاة والسلام عن ذلك بعارض شغل. وإما بأن اللطيف الخبير جل شأنه نظر لأمه حبيبه ومتبعي صفيه ونجيه، فجمع آراءهم المختلفة وأهواءهم المتشتتة، على من هو أكثرهم فضلاً، وأعزهم علماً، وأوفرهم عقلاً،"], [158, "وأصوبهم تدبيراً، وأريضهم عند المسلمات جأشاً، وأشدهم على وعد الله بإظهار الدين على الأديان كلها اتكالاً، وأيمنهم بقسمه، وأظهرهم سريرة، وأعودهم على إغناء الخلق وطبقات الرعايا نفعاً، وأقدمهم إسلاماً، وأجودهم كفاً، وأسمحهم ببذل ما احتوى من المال في ذات الله يداً، وأقلهم في ذات الله تعالى مبالاة عن لومة لائم وملاحاة جاهل ــ فرافضون الله عليه وعلى محبيه ومتبعيه.\rوبأي سبب انعقد الإجماع فهو حجة موجبة قطعاً، ثم الدليل من الكتاب قوله تعالى: {قُلْ لِلْمُخَلَّفِينَ مِنَ الْأَعْرَابِ سَتُدْعَوْنَ إِلَى قَوْمٍ أُولِي بَأْسٍ شَدِيدٍ} [الفتح: 16]؛ أمر الله تعالى نبيه عليه الصلاة والسلام أن يقول للذين تخلفوا عن الغزو معه: \"إنكم ستدعون إلى قوم ألي بأس شديد\"، وأشار في الآية إلى كون ما دعاهم إليه، ويستحقون التعذيب بالعذاب الأليم بعصيانهم إياه، وإعراضهم عن الإجابة إلى ما دعاهم إليه، فإنه تعالى قال: {فَإِنْ تُطِيعُوا يُؤْتِكُمُ اللَّهُ أَجْرًا حَسَنًا وَإِنْ تَتَوَلَّوْا كَمَا تَوَلَّيْتُمْ مِنْ قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا (16)} [الفتح: 16]؛ وهذا هو أمارة كون الداعي مفترض الطاعة، ثم اختلف أهل التأويل في المراد بقوله تعالى: {أُولِي بَأْسٍ شَدِيدٍ}،"], [159, "منهم من قال: \"بنو حنيفة\"، ومنهم من قال: \"هم أهل فارس\"، على ما قال الله تعالى في آية أخرى: {بَعَثْنَا عَلَيْكُمْ عِبَادًا لَنَا أُولِي بَأْسٍ شَدِيدٍ} [الإسراء: 5]، وهم جنود بخت نصر ــ والله أعلم ــ والداعي إلى قتال بني حنيفة أبو بكر الصديق ــ رضي الله عنه ــ فيثبت به خلافته، ويثبت خلافة من عقد هو له واستخلفه؛ وهو عمر بن الخطاب ــ رضي الله عنه ــ والداعي إلى قتال فارس عمر بن الخطاب ــ رضي الله عنه ــ فيثبت به خلافته، وبثبوت خلافته ثبوت خلافة من استخلفه وهو أبو بكر ــ رضي الله عنه ــ فكان في الآية دلالة خلافة الشيخين ــ رضي الله عنهما.\rوالذي يؤيد هذا أن النبي صلى الله عليه وسلم كان أفضل البشر، وسيد الأنبياء، ثم أتباع كل نبي بعد وفاته بقوا الدهر الطويل والأمد المديد على شريعته متمسكين بدينه وسنته، فلا يظن أصحاب رسول الله أجمعوا على باطل، وغصب الحق من مستحقه، ونصب جائر متعد وجلدة رسولهم بعد لم تبرد، هذا والله الظن المحال والقول الباطل.\rثم لو كان أبو بكر ــ رضي الله عنه ــ غصب الحق من على ــ رضي الله عنه ــ كيف لم يشهر على سيفه ولم يطلب حقه؟ وكيف قعدت الصحابة ــ رضي الله عنهم ــ وهم الموصوفون بالأمر بالمعروف والنهي عن المنكر عن نصرته؟ وكيف سلمت الأنصار الأمر لقريش عند"], [160, "قيام الدليل ثم اتبعوا مبطلاً وخذلوا محقاً؟ وأي جبن وضعف كان لعلى ــ رضي الله عنه ــ وعشيرته حتى انقادوا للباطل وذلوا على الظلم والحيف، وصبروا على غصب الحق؟ غير أن الروافض قوم قد ضلوا عن الرشد، وعملوا عن رؤية الصواب والحق.\rوالأمر في صحة خلافة الصديق ــ رضي الله عنه ــ أظهر وأشهر من أن يحتاج إلى أطناب فيه، وقد ذكرت الكلام فيه أعلى الاستقصاء في كتاب \"تبصرة الأدلة\"، والله الموفق.\rوبثبوت خلافة أبي بطر ثبتت خلافة عمرـ رضي الله عنهما ــ لأنه خو الذي ولاه واستخلفه مع ما مر من الأدلة في الكتاب على صحة خلافته، وكذا الإجماع انعقد بعد وفاة الصديق على خلافة عمر ــ رضي الله عنهما ــ لأنه هو الذي ولاه واستخلفه مع ما مر من الأدلة في الكتاب على صحة خلافته، وكذا الإجماع انعقد بعد وفاة الصديق على خلافة عمر ــ رضي الله عنهما ــ و علي ــ رضي الله عنه ــ سلم الأمر له، وزوجه ابنته أم كلثوم، وعلي ــ رضي الله عنه ــ أجل قدراً وأشجع قلباً وأمنع عشيرة من أن يغصب حقه، وأقوى وحرمه حظه. والخبر مشهور عن النبي صلى الله عليه وسلم أنه قال: <اقتدوا باللذين من بعدي أبي بكر وعمر> ــ رضي الله عنهما ــ ثم إن الله تعالى أعز الدين ببركة إمامته، ونشره في أقطار الأرض، وأذل الجبابرة والعتاة منا منه وفضلاً، والله ذو الفضل العظيم.\rثم بعد وفاة عمر ــ رضي الله عنه ــ أجمع من جعل عمر ــ رضي الله عنه ــ والأمر شورى فيما بينهم ــ على خلافة عثمان ــ رضي الله عنه ــ وعقدوا له الخلافة، وكانت جميع شرائط الإمامة فيه"], [161, "ثابتةً؛ فثبت خلافته، ثم قتل مظلوماً شهيداً ــ رضوان الله عليه ــ وكذا علي ــ رضي الله عنه ــ انعقدت خلافته ببيعة من له ولاية البيعة، وهو يومئذٍ أفضل خليقة الله تعالى على وجه الأرض، وأولاهم بها؛ إذا المتولي لها كبار الصحابة، وأئمة الخلق، وخيار من بقى من الصحابة ــ رضي الله عنهم.\rثم وقع الخلاف بعد ذلك بأسباب لا معنى لذكرها هنا لاشتهارها، فلم يوجب ذلك قدحاً فيما انعقد من خلافته وثبت من إمامته.\rوفي صحة خلافة كل واحد من الخلفاء الراشدين ــ رضي الله عنهم أجمعين ــ دلائل جمة، وعليها للخصوم فيه شبهة، وللمخلفين في كل واحد منهم مطاعن، بينا الدلائل، وكشفنا الشبهة، وأظهرنا براءة ساحتهم عما نسب إليهم من المطاعن في كتاب \"تبصرة الأدلة\" على وجه لم يبق للمسترشد شبهة، ولا لمخالف ريبة، ولا لمعاند مقالاً ــ بحمد الله تعالى ــ فير أنا اكتفينا بهذا القدر في هذا الكتاب إيثاراً للتخفيف، وتحاشياً عن إبرام الناظر فيه، واعتماداً على ما ذكرنا هنالك، والله الموفق.\rثم أفضل الأمة بعد نبينا محمد صلى الله عليه وسلم أبو بكر ثم عمر ثم عثمان ثم على ــ رضي الله عنهم أجمعين ــ دليله: ما روى أبو داود، وسليمان بن الأشعث السجستاني في كتاب \"السنن\" بإسناده عن عمر ــ رضي الله عنه ــ أنه قال: \"كنا نقول في زمن رسول الله صلى الله عليه وسلم: لا نعدل بأبي بكر أحداً ثم"], [162, "عمر ثم علي، وقد روى أيضاً عن ابن عمر ــ رضي الله عنهما ــ أنه قال: كنا نقول ــ ورسول الله حي ــ أفضل أمة النبي صلى الله عليه وسلم بعده أبو بكر ثم عمر ثم عثمان ثم علي ــ رضي الله عنهم ــ\" وروى أبو داود أيضاً عن محمد بن الحنيفة ــ رضي الله عنه ــ أنه قال: \"قلت لأبي: أي الناس خير بعد رسول صلى الله عليه وسلم؟ \"، قال: \"أبو بكر\"، قلت: \"ثم من؟ \"، قال: \"ثم عمر\"، قال: ثم خشيت أن أقول: ثم من، فيقول: عثمان\"، فقلت: \"ثم أنت يا أبت؟ \"، فقال: \" ما أنا إلا رجل من المسلمين\"؛ فثبت بهذه الأحاديث ما ادعينا من الترتيب. وفي فضل الترتيب في الفضيلة اختلاف بين الناس، وفيه كلام كثير ودلائل جمة ذكرت بعضها في كتاب \"تبصرة الأدلة\"، وكتبنا هذا يضيق عن ذكر ذلك، والله الموفق، اللهم بصرنا الخير حيث كان."], [163, "تم الكتاب بعون الملك التواب، "]], "pg": [155, 163]}, "466.21": {"x": [[163, "وهو أعلم بالصواب، وإليه المرجع والمآب.\rوافق الفراغ من نسخها يوم السبت سادس عشرين جمادى الآخرة سنة أربع وثمانمائة\rعلى يد العبد الفقير المعترف بالتقصير، الراجي عفو ربه القوى اللطف الحفي\rيوسف أحمد الأدهمي الحنفي\rبالقاهرة المحروسة ــ غفر الله له ولوالديه، ولكل المسلمين أجمعين.\rوصلى الله على سيدنا محمد وآله وصحبه أجمعين، وسلم تسلماً كثيراً إلى يوم الدين.\rوالحمد الله لله رب العالمين، وحسبنا الله ونعم الوكيل.\rتحقيق\rمحمد عبد الرحمن الشاغول الشافعي الأشعري"], [164, "مرشدة\r"]], "pg": [163, 164]}, "466.22": {"x": [[164, "اعلم أرشدنا الله تعالى وإياك: أنه واجب على كل مكلف أن يعلم أن الله عز وجل واحد في ملكه، خلق العالم بأسره العلوي والسفلي، والعرش والكرسي، والسموات والأرض وما فيهما، وما بينهما، جميع الخلائق مقهورون بقدرته، لا تتحرك ذرة إلا بأذنه، ليس معه مدبر في الخلق، ولا شريك له في الملك، حي قيوم، لا تأخذه سنة ولا نوم، عالم الغيب والشهادة، لا يخفى عليه شيء في السماء ولا في الأرض، يعلم ما في البر والبحر، وما تسقط من ورقة إلا يعلمها، ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين، أحاط بكل شيء علماً، وأحصى كل شيء عدداً، فعال لما يريد، قادر على ما يشاء له الملك والغني، وله العزة والبقا، وله الحكم والقضا، وله الأسماء الحسنى، لا دافع لما قضى، ولا مانع لما أعطى، يفعل في ملكه ما يريد، ويحكم في خلقه ما يشاء، لا يرجو ثواباً، ولا يخاف عقاباً، ليس عليه حق، ولا عليه حكم، وكل نعمة منه فضل، وكل نقمة منه عدل، لا يسأل عما يفعل وهم يسألون، موجود قلب الخلق، ليس له قبل ولا بعد، ولا فوق ولا تحت، ولا يمين ولا شمال، ولا خلف ولا أمام، ولا كل ولا بعض، لا يقال متى كان، ولا أين كان، ولا كيف كان، كان ولا مكان، ودبر الزمان، لا يتقيد بالزمان، ولا يتخصص بالمكان، ولا يلحقه وهم، ولا يكيفه عقل، ولا يتخصص في الذهن، ولا يتمثل في النفس، ولا يتصور في الوهم، ولا\rيتكيف في العقل، لا تلحقه الأوهام والأفكار، ولا تحويه الجهات والأقطار، ليس كمثله شيء وهو السميع البصير، عرفه العارفون بأفعاله، ونفوا التكييف عن جلاله، فكل ما خطر في الأوهام والأفكار فالله تعالى بخلافه."], [165, "تمت المرشدة بعون الله تعالى\r"]], "pg": [164, 165]}, "466.23": {"x": [[165, "وحسن توفيقه\rوصلى الله على خير خلقه وآله وسلم"]], "pg": [165, 165]}}, "units": {"49": {"tit": "فصل في إثبات الإرادة", "lvl": 1, "pg": [59, 62]}, "52": {"tit": "فصل في أن صانع العالم حكيم", "lvl": 1, "pg": [62, 64]}, "54": {"tit": "فصل في إثبات رؤية الله تعالى في العقل دليل على جواز رؤية الله تعالى", "lvl": 1, "pg": [64, 68]}, "58": {"tit": "فصل في إثبات الرسالة", "lvl": 1, "pg": [68, 80]}, "70": {"tit": "ومعجزاته العقلية منقسمة إلى أقسام كثيرة", "lvl": 1, "pg": [80, 82]}, "72": {"tit": "فصل في إثبات كرامات الأولياء", "lvl": 1, "pg": [82, 85]}, "75": {"tit": "فصل في الاستطاعة مع الفعل", "lvl": 1, "pg": [85, 93]}, "83": {"tit": "فصل في إثبات خلق أفعال العباد", "lvl": 1, "pg": [93, 107]}, "97": {"tit": "فصل في أن المتولدات مخلوقة لله تعالى", "lvl": 1, "pg": [107, 109]}, "99": {"tit": "فصل في أن المقتول ميت بأجله", "lvl": 1, "pg": [109, 111]}, "101": {"tit": "فصل في الأرزاق", "lvl": 1, "pg": [111, 112]}, "102": {"tit": "فصل في أن المعاصي بإرادة الله تعالى ومشيئته", "lvl": 1, "pg": [112, 121]}, "111": {"tit": "فصل في القضاء والقدر وثبوت كون أفعال الخلق مخلوقة لله تعالى", "lvl": 1, "pg": [121, 123]}, "113": {"tit": "فصل في الهدى والإضلال وثبوت خلق الأفعال", "lvl": 1, "pg": [123, 124]}, "114": {"tit": "فصل في إبطال القول بالأصلح وثبوت مسألة خلق الأفعال وكون الكفر والمعاصي مخلوقة لله تعالى وإن كان يتضرر بهما الكفار والعصاة", "lvl": 1, "pg": [124, 132]}, "122": {"tit": "فصل في إثبات عذاب القبر للكافرين ولبعض العصاة من المؤمنين، والإنعام لأهل الطاعة في القبر", "lvl": 1, "pg": [132, 134]}, "124": {"tit": "فصل في وعيد فساق المسلمين", "lvl": 1, "pg": [134, 144]}, "134": {"tit": "فصل في إثبات الشفاعة", "lvl": 1, "pg": [144, 146]}, "136": {"tit": "فصل في ماهية الإيمان", "lvl": 1, "pg": [146, 155]}, "145": {"tit": "فصل في الأمامة", "lvl": 1, "pg": [155, 163]}, "153": {"tit": "تم الكتاب بعون الملك التواب", "lvl": 1, "pg": [163, 164]}, "157": {"tit": "مرشدة", "lvl": 1, "pg": [164, 165]}, "158": {"tit": "تمت المرشدة بعون الله تعالى", "lvl": 1, "pg": [165, 165]}}};
